/* ===== 03g_qa.js ===== */
// Частые детские вопросы и короткие проверенные ответы (работают без интернета). Создаётся tools/merge_data.js.
const QA_DATA = [
  {"q":["сколько костей у человека","сколько костей в теле человека","скока костей у людей","сколько у меня костей"],"a":"У взрослого человека 206 костей. А у новорождённого малыша их почти 300 — со временем некоторые из них срастаются между собой. 🦴"},
  {"q":["зачем нам спать","почему мы спим","зачем человеку сон","зачем нужно спать"],"a":"Во сне тело отдыхает и восстанавливается, а мозг раскладывает по полочкам всё, что ты узнал за день. Детям сон особенно важен: именно во сне организм активно растёт. 😴"},
  {"q":["почему мы зеваем","зачем люди зевают","почему хочется зевать","почему зевота заразная"],"a":"Учёные до сих пор точно не знают! Есть версия, что зевок немного охлаждает мозг и помогает взбодриться. А ещё зевота заразная: увидишь, как кто-то зевает, — и сам тоже захочешь. 🥱"},
  {"q":["почему мы чихаем","зачем люди чихают","почему человек чихает","отчего бывает чих"],"a":"Чих — это защита: так нос резко выдувает пыль, пыльцу или микробов, которые попали внутрь. Когда чихаешь, прикрывай рот и нос локтем или платком. 🤧"},
  {"q":["зачем чистить зубы","почему надо чистить зубы","зачем каждый день чистить зубы","а если не чистить зубы что будет"],"a":"На зубах живут бактерии: они едят остатки еды, особенно сладкой, и выделяют кислоту, которая делает в зубах дырочки — кариес. Чисти зубы два раза в день по 2 минуты, и они будут крепкими. 🪥"},
  {"q":["почему бывают мурашки","откуда берутся мурашки по коже","почему по коже бегут мурашки","почему гусиная кожа"],"a":"У каждого волоска на коже есть крошечная мышца. Когда холодно, страшно или очень волнительно, эти мышцы сжимаются, волоски приподнимаются — и появляются мурашки. У наших далёких предков с густой шерстью это помогало согреться. 🥶"},
  {"q":["как работает сердце","что делает сердце","зачем человеку сердце","как устроено сердце"],"a":"Сердце — это сильная мышца размером примерно с твой кулак. Оно, как насос, сжимается и гонит кровь по сосудам ко всему телу и бьётся около 100 000 раз в день. ❤️"},
  {"q":["сколько раз в минуту бьётся сердце","какой пульс у человека","сколько ударов делает сердце","какой нормальный пульс"],"a":"У взрослого в спокойном состоянии сердце бьётся примерно 60–100 раз в минуту, а у детей немного чаще. Когда бегаешь или волнуешься, оно стучит гораздо быстрее. 💓"},
  {"q":["почему у людей разный цвет глаз","от чего зависит цвет глаз","почему у меня карие глаза","почему глаза бывают голубые и карие"],"a":"Цвет глаз зависит от того, сколько в радужке пигмента меланина: много — глаза карие, мало — голубые, серые или зелёные. Какими будут глаза, решают гены, полученные от мамы и папы. На Земле больше всего людей с карими глазами. 👀"},
  {"q":["откуда появились люди","как появились люди","откуда взялся человек","как появился первый человек"],"a":"Люди появились благодаря эволюции: живые существа очень медленно, за миллионы лет и множество поколений, менялись, и выживали те, кому изменения помогали. Так от древних предков постепенно произошёл человек разумный — примерно 300 000 лет назад в Африке. 🌍"},
  {"q":["человек произошёл от обезьяны","правда что люди произошли от обезьян","люди были обезьянами","мы произошли от обезьяны"],"a":"Не совсем! Люди произошли не от сегодняшних обезьян: у нас и у шимпанзе был общий древний предок, живший примерно 6–7 миллионов лет назад. Потом одни его потомки постепенно стали людьми, а другие — шимпанзе. 🐒"},
  {"q":["сколько зубов у человека","сколько зубов у взрослого","скока зубов у людей","сколько зубов у детей"],"a":"У взрослого человека обычно 32 зуба, включая 4 зуба мудрости, которые вырастают не у всех. А у детей 20 молочных зубов. 🦷"},
  {"q":["почему выпадают молочные зубы","зачем выпадают зубы у детей","почему у меня шатается зуб","когда выпадают молочные зубы"],"a":"Под молочными зубами в челюсти уже растут большие и крепкие постоянные зубы. Они подталкивают молочные, корни молочных зубов постепенно рассасываются — зуб начинает шататься и выпадает. Обычно это начинается около 6 лет, и это совсем нормально. 🦷"},
  {"q":["сколько мышц у человека","сколько мышц в теле","скока у человека мышц","сколько всего мышц у людей"],"a":"У человека больше 600 мышц! Они помогают нам ходить, улыбаться, моргать, дышать, а самая главная работящая мышца — сердце. 💪"},
  {"q":["какая самая большая кость у человека","самая длинная кость в теле","какая кость самая большая","самая большая кость в организме"],"a":"Самая большая и длинная кость — бедренная, она находится в ноге между тазом и коленом. Она очень прочная и выдерживает огромную нагрузку. 🦵"},
  {"q":["какая самая маленькая кость у человека","самая маленькая кость в теле","где самая маленькая косточка","самая крошечная кость"],"a":"Самая маленькая кость — стремечко, она находится внутри уха и размером всего около 3 миллиметров. Она помогает нам слышать. 👂"},
  {"q":["какой самый большой орган у человека","самый большой орган в теле","какой орган самый большой","самый большой орган человека"],"a":"Самый большой орган — кожа! У взрослого её площадь почти 2 квадратных метра. Она защищает нас от микробов, солнца, холода и помогает чувствовать прикосновения. ✋"},
  {"q":["сколько крови в человеке","сколько литров крови у человека","скока крови в теле","сколько крови у ребёнка"],"a":"У взрослого человека около 5 литров крови. У ребёнка поменьше — примерно 2–4 литра, в зависимости от роста и веса. 🩸"},
  {"q":["почему кровь красная","отчего кровь красного цвета","почему кровь красного цвета","зачем крови красный цвет"],"a":"Кровь красная из-за гемоглобина — вещества с железом внутри красных кровяных клеток. Гемоглобин переносит кислород по всему телу. 🩸"},
  {"q":["почему вены синие","почему кровь в венах синяя","почему вены синего цвета","кровь бывает синей"],"a":"На самом деле кровь у человека всегда красная, в венах она просто тёмно-красная. Вены кажутся синими из-за того, как свет проходит через кожу и отражается от неё. 💙"},
  {"q":["зачем нужна кровь","что делает кровь","зачем человеку кровь","для чего нужна кровь"],"a":"Кровь развозит по телу кислород и полезные вещества из еды, а забирает отходы. В ней есть клетки, которые сражаются с микробами, и клетки, которые останавливают кровь, если поранишься. 🚑"},
  {"q":["как работает мозг","что делает мозг","зачем человеку мозг","как мы думаем"],"a":"Мозг — это командный центр тела. В нём около 86 миллиардов нервных клеток, которые передают друг другу крошечные сигналы, — так мы думаем, запоминаем, чувствуем и двигаемся. Мозг работает даже во сне! 🧠"},
  {"q":["сколько весит мозг","сколько весит мозг человека","какой вес у мозга","тяжёлый ли мозг"],"a":"Мозг взрослого человека весит примерно 1,3–1,4 килограмма — как небольшая дыня. При этом он тратит около пятой части всей энергии тела. 🧠"},
  {"q":["правда что мы используем только 10 процентов мозга","мы используем 10 процентов мозга","человек использует мозг на 10 процентов","мозг работает только на 10%"],"a":"Это миф! Учёные с помощью приборов видят, что работают все части мозга, просто разные — в разное время. Даже во сне мозг очень занят. 🧠"},
  {"q":["зачем нам дышать","почему мы дышим","зачем человеку воздух","зачем нужен кислород"],"a":"Каждой клетке тела нужен кислород, чтобы получать энергию из еды. Мы вдыхаем воздух с кислородом, а выдыхаем углекислый газ, который телу не нужен. 🌬️"},
  {"q":["как работают лёгкие","что делают лёгкие","зачем нужны лёгкие","как устроены легкие"],"a":"Лёгкие похожи на губки с миллионами крошечных пузырьков. Когда вдыхаешь, кислород из пузырьков переходит в кровь, а углекислый газ — из крови в лёгкие, и ты его выдыхаешь. 🫁"},
  {"q":["почему мы икаем","отчего бывает икота","почему я икаю","как перестать икать"],"a":"Икота бывает, когда диафрагма — мышца под лёгкими — вдруг резко сжимается, а голосовые связки быстро захлопываются: вот и получается «ик». Обычно она проходит сама, иногда помогает медленно попить воды маленькими глотками. 💧"},
  {"q":["почему урчит в животе","почему бурчит живот","почему живот урчит когда голодный","отчего урчание в животе"],"a":"Мышцы желудка и кишечника всё время сжимаются и проталкивают еду, жидкость и воздух. Когда живот пустой, звук становится громче — получается урчание. Так живот будто говорит: «Пора перекусить!» 🍽️"},
  {"q":["почему мы потеем","зачем человек потеет","зачем нужен пот","почему я потею когда бегаю"],"a":"Пот охлаждает тело. Когда жарко или ты много двигаешься, кожа выделяет пот, он испаряется и уносит с собой лишнее тепло. 💦"},
  {"q":["зачем нам волосы","зачем человеку волосы","зачем нужны волосы","зачем нужны брови и ресницы"],"a":"Волосы на голове защищают от солнца и холода. Брови не дают поту стекать в глаза, ресницы защищают глаза от пыли, а волоски в носу задерживают пылинки. 💇"},
  {"q":["почему седеют волосы","почему бабушка седая","отчего волосы становятся белыми","почему у старых людей седые волосы"],"a":"Цвет волосам даёт пигмент меланин. С возрастом его вырабатывается всё меньше, и новые волосы растут без краски — седыми. 👵"},
  {"q":["зачем нам ногти","зачем человеку ногти","почему не больно стричь ногти","почему не больно стричь волосы"],"a":"Ногти защищают кончики пальцев и помогают брать мелкие предметы. Ногти и волосы состоят из прочного вещества кератина, в них нет нервов — поэтому стричь их не больно. 💅"},
  {"q":["почему у людей разный цвет кожи","почему бывают темнокожие люди","от чего зависит цвет кожи","почему люди разного цвета"],"a":"Цвет кожи зависит от пигмента меланина. У предков, живших в очень солнечных краях, кожа стала темнее, чтобы защищаться от солнца, а там, где солнца меньше, — светлее. Но все люди на Земле — один вид, и внутри мы устроены одинаково. 🤝"},
  {"q":["почему появляются веснушки","откуда берутся веснушки","что такое веснушки","почему у меня веснушки"],"a":"Веснушки — это маленькие пятнышки, где кожа сделала побольше пигмента меланина. Они чаще появляются от солнца и передаются по наследству. Веснушки совершенно безвредны и очень милые! 🌞"},
  {"q":["почему люди загорают","почему от солнца темнеет кожа","почему сгорают на солнце","зачем мазаться кремом от солнца"],"a":"Загар — это защита: кожа делает больше меланина, чтобы прикрыться от солнечных лучей. Но если солнца слишком много, кожа обгорает, поэтому летом нужны панамка и солнцезащитный крем. 🧴"},
  {"q":["почему поднимается температура когда болеешь","зачем при болезни температура","почему у меня жар","отчего бывает температура"],"a":"Так организм борется с микробами: многим из них жара не нравится, а защитные клетки при ней работают активнее. Если у тебя температура, обязательно скажи взрослым и отдыхай. 🤒"},
  {"q":["какая нормальная температура тела","какая температура должна быть у человека","нормальная температура человека","сколько градусов у здорового человека"],"a":"Обычно температура здорового человека около 36,6 °C, а нормой считается примерно от 36 до 37 градусов. 🌡️"},
  {"q":["почему мы болеем","что такое микробы","откуда берутся болезни","почему люди болеют"],"a":"Многие болезни вызывают микробы — крошечные бактерии и вирусы, которых не видно без микроскопа. Когда они попадают в тело, иммунитет начинает с ними сражаться, и мы какое-то время чувствуем себя плохо. 🦠"},
  {"q":["зачем мыть руки","почему надо мыть руки","зачем мыть руки с мылом","почему мыть руки перед едой"],"a":"На руках собираются микробы, а мыло помогает их смыть. Мой руки с мылом секунд 20–30 перед едой, после туалета и после прогулки. 🧼"},
  {"q":["что такое иммунитет","как работает иммунитет","зачем нужен иммунитет","что такое иммунная система"],"a":"Иммунитет — это защитная армия тела. Особые клетки крови находят микробов и уничтожают их, а ещё запоминают «врагов», чтобы в следующий раз справиться быстрее. 🛡️"},
  {"q":["зачем делают прививки","зачем нужны прививки","что такое прививка","почему ставят прививки"],"a":"Прививка учит иммунитет узнавать опасного микроба заранее, без настоящей тяжёлой болезни. Потом, если встретишь этого микроба, тело уже будет знать, как его победить. 💉"},
  {"q":["почему нельзя есть много сладкого","почему сладкое вредно","чем вредны конфеты","что будет если есть много конфет"],"a":"Сахаром питаются бактерии во рту, которые портят зубы, а лишнее сладкое вредит здоровью и даёт мало пользы. Немножко сладкого можно, главное — не вместо обычной еды. 🍬"},
  {"q":["почему мы любим сладкое","почему так хочется сладкого","почему конфеты такие вкусные","почему все любят сладкое"],"a":"Сладкий вкус для мозга — сигнал «тут много энергии». Для наших древних предков сладкие спелые фрукты были ценной едой, поэтому мозг до сих пор радуется сладкому. 🍓"},
  {"q":["зачем есть овощи и фрукты","почему надо есть овощи","что такое витамины","зачем нужны витамины"],"a":"В овощах и фруктах много витаминов и минералов — это маленькие помощники, без которых тело не может нормально расти и работать. Ещё в них есть клетчатка, которая помогает животу. 🥕"},
  {"q":["сколько нужно пить воды","сколько воды надо пить в день","зачем пить воду","сколько стаканов воды пить"],"a":"Наше тело больше чем наполовину состоит из воды, и её нужно пополнять. Детям обычно хватает около 6–8 стаканов воды и других напитков в день, а в жару или при беготне — больше. Лучше всего пить чистую воду, когда хочется. 💧"},
  {"q":["сколько нужно спать детям","сколько часов надо спать","сколько должен спать ребёнок","сколько спать школьнику"],"a":"Детям от 6 до 12 лет нужно спать примерно 9–12 часов, а подросткам — 8–10 часов. Если хорошо высыпаешься, легче учиться и меньше болеешь. 🛏️"},
  {"q":["почему снятся сны","откуда берутся сны","зачем нам сны","почему мы забываем сны"],"a":"Во сне мозг продолжает работать и перемешивает воспоминания, мысли и чувства — так и получаются сны. Зачем они нужны, учёные ещё изучают. А забываем мы их, скорее всего, потому, что во сне мозг плохо записывает новые воспоминания. 💭"},
  {"q":["вредно ли долго сидеть в телефоне","почему от телефона болят глаза","экран портит зрение","почему устают глаза от компьютера"],"a":"Когда мы долго смотрим в экран, то реже моргаем, и глаза устают и пересыхают. Учёные также считают, что если много времени смотреть на близкие предметы и мало гулять на улице, зрение вдаль может ухудшиться. Каждые 20 минут смотри вдаль и чаще гуляй на улице. 📱"},
  {"q":["почему люди носят очки","зачем нужны очки","почему плохо видят","почему у меня очки"],"a":"Иногда глаз фокусирует свет не совсем точно: при близорукости плохо видно вдаль, при дальнозоркости — вблизи. Очки помогают глазу собрать картинку чётко. 👓"},
  {"q":["как мы видим","как работают глаза","как глаз видит","как устроен глаз"],"a":"Свет проходит через прозрачную роговицу и зрачок, а хрусталик, как маленькая линза, помогает собрать его на сетчатке — и она отправляет сигналы в мозг. Интересно, что на сетчатке картинка перевёрнута, но мозг всё равно понимает её правильно! 👁️"},
  {"q":["как мы слышим","как работают уши","как ухо слышит звук","как устроено ухо"],"a":"Звук — это колебания воздуха. Они попадают в ухо, заставляют дрожать барабанную перепонку и три крошечные косточки, а внутри уха «улитка» превращает их в сигналы для мозга. 👂"},
  {"q":["сколько вкусов чувствует язык","как язык чувствует вкус","какие бывают вкусы","почему когда насморк еда невкусная"],"a":"На языке тысячи крошечных вкусовых почек, они различают пять основных вкусов: сладкий, солёный, кислый, горький и умами — «бульонный». А ещё вкус сильно зависит от запаха, поэтому при насморке еда кажется пресной. 👅"},
  {"q":["сколько у человека органов чувств","какие есть органы чувств","какие бывают чувства у человека","сколько чувств у человека"],"a":"Обычно называют пять: зрение, слух, обоняние, вкус и осязание. Но учёные добавляют ещё чувство равновесия, чувство боли, тепла и холода и ощущение положения своего тела. 🖐️"},
  {"q":["почему кружится голова","почему голова кружится когда покружишься","отчего кружится голова после карусели","почему кружится голова после вращения"],"a":"Внутри уха есть крошечные каналы с жидкостью — они отвечают за равновесие. Когда ты остановился, жидкость ещё какое-то время крутится, и мозгу кажется, что ты всё ещё вертишься. 😵‍💫"},
  {"q":["зачем человеку пупок","откуда у нас пупок","почему у людей есть пупок","что такое пупок"],"a":"Пока малыш растёт у мамы в животе, он получает еду и кислород через пуповину. После рождения её перерезают — это не больно, — а на память остаётся пупок. 🤰"},
  {"q":["откуда берутся дети","как появляются дети","откуда появляются малыши","как рождаются дети"],"a":"Малыш начинается с двух крошечных клеток — одной от мамы и одной от папы. Потом он около 9 месяцев растёт в особом месте у мамы в животе, которое называется матка, и рождается. Подробнее об этом лучше спросить у родителей. 👶"},
  {"q":["почему люди стареют","почему бабушки и дедушки старые","зачем люди стареют","почему появляются морщины"],"a":"С годами клетки тела хуже обновляются и чинят себя, кожа становится менее упругой, и появляются морщины. Это естественная часть жизни, а учёные изучают, как помочь людям дольше оставаться здоровыми. 👴"},
  {"q":["почему люди растут","до скольки лет растёт человек","когда я перестану расти","почему мы растём"],"a":"Кости растут в длину благодаря особым «зонам роста» у их концов, а помогает им гормон роста — больше всего его вырабатывается во сне. Девочки обычно растут примерно до 14–16 лет, а мальчики — до 16–18, иногда чуть дольше. 📏"},
  {"q":["почему мы плачем","зачем нужны слёзы","почему текут слёзы","почему люди плачут"],"a":"Слёзы всё время понемногу увлажняют и промывают глаза. А когда нам очень грустно, больно или даже радостно, слёз становится много — плач помогает выпустить сильные чувства. 😢"},
  {"q":["почему текут сопли","зачем нужны сопли","откуда берутся сопли","почему при простуде сопли"],"a":"Слизь в носу ловит пыль и микробов. Во время простуды нос делает её больше, чтобы вымыть микробов наружу. Сморкайся в платок и мой руки. 🤧"},
  {"q":["почему мы кашляем","зачем человек кашляет","отчего бывает кашель","почему я кашляю"],"a":"Кашель — это способ тела очистить горло и лёгкие от слизи, пыли или крошек. Кашляй в локоть или платок, а если кашель долгий — скажи взрослым. 😷"},
  {"q":["почему нельзя пощекотать самого себя","почему не щекотно когда сам себя щекочешь","почему я не могу себя защекотать","почему щекотно только когда другие"],"a":"Мозг заранее знает, что сейчас будут делать твои пальцы, и не удивляется. А щекотка срабатывает как раз от неожиданности, поэтому себя защекотать почти невозможно. 😄"},
  {"q":["почему затекает нога","почему отсидел ногу","почему нога колется иголочками","почему немеет рука"],"a":"Когда долго сидишь в неудобной позе, ты пережимаешь нервы и сосуды, и нога «засыпает». Как только меняешь позу, нервы снова начинают работать — отсюда колючие иголочки. 🦶"},
  {"q":["почему есть левши и правши","почему люди левши","почему я пишу левой рукой","почему большинство правши"],"a":"Какой рукой удобнее, зависит от устройства мозга и генов. Левшей примерно 10 % людей, и это совершенно нормально — ни левши, ни правши не лучше друг друга. ✍️"},
  {"q":["почему отпечатки пальцев у всех разные","что такое отпечатки пальцев","у близнецов одинаковые отпечатки пальцев","зачем узоры на пальцах"],"a":"Узоры на пальцах складываются ещё до рождения, пока малыш растёт у мамы в животе, и потом не меняются всю жизнь. Они уникальны у каждого — даже у однояйцевых близнецов они разные! Учёные думают, что эти бороздки помогают пальцам лучше чувствовать мелкие неровности. 👆"},
  {"q":["почему болят мышцы после спорта","почему после тренировки болит тело","почему болят ноги после физры","отчего мышцы болят на следующий день"],"a":"После непривычной нагрузки в мышцах появляются крошечные повреждения. Тело их чинит за 1–3 дня, и мышцы становятся немного сильнее. 🏋️"},
  {"q":["зачем заниматься спортом","почему полезно двигаться","зачем нужна физкультура","зачем делать зарядку"],"a":"Движение укрепляет сердце, лёгкие, мышцы и кости, а ещё улучшает настроение и сон. Детям полезно активно двигаться хотя бы час каждый день — бегать, плавать, играть. ⚽"},
  {"q":["куда девается еда","как переваривается еда","как работает желудок","что происходит с едой в животе"],"a":"Еда пережёвывается во рту, по пищеводу попадает в желудок, а потом в кишечник, где полезные вещества всасываются в кровь. Всё ненужное выходит в туалете, а весь путь обычно занимает от одного до трёх дней. 🍎"},
  {"q":["почему мы пукаем","почему люди пукают","откуда берутся газы","зачем человек пукает"],"a":"В кишечнике живут полезные бактерии, которые помогают переваривать еду и при этом делают газы. Им нужно куда-то выходить — это совершенно нормально, так делают абсолютно все люди. 😅"},
  {"q":["почему появляются синяки","откуда берутся синяки","почему синяк меняет цвет","что такое синяк"],"a":"При ударе под кожей лопаются крошечные сосуды, и немного крови вытекает — получается синяк. Пока тело его убирает, он меняет цвет с сине-фиолетового на зеленоватый и жёлтый. 🩹"},
  {"q":["как заживает ранка","почему на ранке корочка","зачем корочка на ране","почему нельзя сдирать корочку"],"a":"Когда поранишься, особые клетки крови склеиваются и закрывают ранку, а сверху получается корочка — она защищает, пока под ней растёт новая кожа. Корочку лучше не сдирать, а если рана глубокая — сразу скажи взрослым. 🩹"},
  {"q":["что такое аллергия","почему бывает аллергия","отчего аллергия","почему у меня аллергия на кошку"],"a":"Аллергия — это когда иммунитет по ошибке сражается с безобидными вещами: пыльцой, пылью или какой-то едой. Аллергию на кошку вызывает не сама шерсть, а особые белки из слюны и кожи кошки, которые остаются на шерсти. Получаются чих, зуд или сыпь. Если трудно дышать — сразу зови взрослых! 🌼"},
  {"q":["почему мы моргаем","зачем люди моргают","сколько раз мы моргаем","зачем моргать"],"a":"Моргая, мы увлажняем и очищаем глаза, а ещё защищаем их от пылинок. Обычно человек моргает примерно 15–20 раз в минуту и даже не замечает этого. 😉"},
  {"q":["сколько живёт человек","сколько лет живут люди","кто прожил дольше всех","самый старый человек в мире"],"a":"Во многих странах люди в среднем живут около 70–80 лет. Дольше всех, по надёжным документам, прожила француженка Жанна Кальман — 122 года! 🎂"},
  {"q":["почему у мальчиков ломается голос","почему голос становится грубым","что такое ломка голоса","почему у папы низкий голос"],"a":"Когда мальчики взрослеют, у них растёт гортань, а голосовые связки становятся длиннее и толще — поэтому голос становится ниже. Пока это происходит, он может смешно «прыгать». У девочек голос тоже немного меняется. 🗣️"},
  {"q":["почему люди разного роста","от чего зависит рост","почему одни высокие а другие низкие","какой самый высокий человек"],"a":"Рост зависит в основном от генов родителей, а ещё от питания, сна и движения. Самым высоким человеком в истории был американец Роберт Уодлоу — 272 сантиметра! 📏"},
  {"q":["почему близнецы похожи","почему у близнецов одинаковые лица","как получаются близнецы","почему близнецы одинаковые"],"a":"Однояйцевые близнецы получаются, когда одна крошечная клетка делится на две, и из каждой растёт малыш, — поэтому гены у них одинаковые. А разнояйцевые близнецы растут из двух разных клеток, поэтому похожи друг на друга, как обычные братья и сёстры. 👯"},
  {"q":["почему я похож на маму и папу","что такое гены","что такое днк","почему дети похожи на родителей"],"a":"Почти в каждой клетке тела есть ДНК — как книга с инструкцией, каким будет тело. Отдельные «главы» этой книги называются генами. Половину инструкции ты получил от мамы, половину от папы, поэтому похож на обоих, но всё равно ты — единственный такой! 🧬"},
  {"q":["сколько клеток в теле человека","что такое клетка","из чего состоит человек","сколько клеток у человека"],"a":"Клетки — это крошечные «кирпичики», из которых построено тело. По подсчётам учёных, у взрослого их примерно 30 триллионов! 🔬"},
  {"q":["зачем нам боль","почему мы чувствуем боль","почему бывает больно","зачем человеку боль"],"a":"Боль — это сигнал тревоги: нервы сообщают мозгу, что с телом что-то не так, чтобы мы быстрее отдёрнули руку или позаботились о себе. Если что-то сильно или долго болит, обязательно скажи взрослым. 🚨"},
  {"q":["почему мы дрожим от холода","почему трясёт когда холодно","зачем дрожать на холоде","почему стучат зубы от холода"],"a":"Когда холодно, мышцы начинают быстро-быстро сжиматься, и от этой работы появляется тепло. Так тело само себя согревает. 🥶"},
  {"q":["почему закладывает уши в самолёте","почему болят уши в самолёте","почему в самолете закладывает уши","что делать если заложило уши"],"a":"Когда самолёт взлетает или снижается, давление воздуха снаружи меняется, и барабанная перепонка прогибается. Помогает глотать, зевать или жевать — так давление внутри уха выравнивается. ✈️"},
  {"q":["почему болит голова","отчего болит голова","что делать если болит голова","у меня болит голова"],"a":"Голова может болеть от усталости, недосыпа, голода, если мало пил воды или долго сидел за экраном, а иногда при болезни. Отдохни, попей воды и обязательно скажи взрослым; лекарства можно пить только вместе с ними. 🤕"},
  {"q":["почему укачивает в машине","почему тошнит в машине","почему меня укачивает","что делать если укачивает"],"a":"Глаза видят, что ты сидишь на месте, а внутреннее ухо чувствует движение — мозг путается, и начинает тошнить. Помогает смотреть в окно вдаль, а не в телефон или книгу, и дышать свежим воздухом. 🚗"},
  {"q":["что такое эмоции","зачем нужны эмоции","какие бывают эмоции","что такое чувства"],"a":"Эмоции — это то, как мозг и тело откликаются на происходящее: радость, грусть, злость, страх, удивление, отвращение. Все эмоции нормальные и нужные — они как сигналы, которые подсказывают, что для тебя важно. 🎭"},
  {"q":["почему мне грустно","что делать если грустно","мне грустно","почему бывает грустно"],"a":"Грусть бывает у всех — когда что-то не получилось, что-то потерял или скучаешь. Она проходит, и легче становится, если рассказать о ней близкому человеку, обняться, порисовать или погулять. 💙"},
  {"q":["почему мы злимся","что делать если злюсь","я злюсь","как перестать злиться"],"a":"Злость появляется, когда что-то кажется несправедливым или не получается. Злиться нормально, а вот обижать других — нет: остановись, глубоко подыши, посчитай до 10 и скажи словами «я злюсь, потому что…». 😤"},
  {"q":["зачем нужен страх","почему мы боимся","что такое страх","почему людям страшно"],"a":"Страх — наш защитник: он предупреждает об опасности и готовит тело быстро убежать или спрятаться. Бояться не стыдно, даже самые смелые люди иногда боятся. 🦁"},
  {"q":["почему я боюсь темноты","что делать если страшно ночью","страшно спать одному","боюсь темноты"],"a":"Темноты боятся очень многие дети: когда мало видно, воображение само дорисовывает страшилки. Монстров не бывает! Расскажи родителям, включи ночник и возьми с собой любимую игрушку. 🌙"},
  {"q":["что такое любовь","что значит любить","почему люди любят","как понять что любишь"],"a":"Любовь — это тёплое чувство, когда человек тебе очень дорог, ты о нём заботишься и хочешь, чтобы ему было хорошо. Любить можно родителей, друзей, бабушку с дедушкой и даже своего котика. ❤️"},
  {"q":["почему бывает скучно","что делать если скучно","мне скучно","чем заняться когда скучно"],"a":"Скука — это мозг говорит: «Хочу чего-нибудь нового!» Из скуки часто рождаются отличные идеи: порисуй, построй что-нибудь, почитай или попроси меня загадать загадку. 🎨"},
  {"q":["как найти друга","как подружиться","у меня нет друзей","как завести друзей"],"a":"Начни с простого: улыбнись, поздоровайся и спроси, чем человек любит заниматься, или позови вместе поиграть. Дружба растёт постепенно, и главное — оставаться собой и быть добрым. 🤝"},
  {"q":["что делать если обижают в школе","меня обижают","меня дразнят в школе","что делать если бьют одноклассники"],"a":"Ты не виноват, и терпеть это не нужно. Обязательно расскажи взрослым, которым доверяешь, — родителям, учителю или школьному психологу: это не ябедничество, а защита себя. 🛡️"},
  {"q":["почему я ревную","что такое ревность","я ревную маму к брату","почему родители любят брата больше"],"a":"Ревность — это страх, что любви и внимания тебе достанется меньше, например когда появился младший брат или сестра. Это нормальное чувство: расскажи о нём родителям — любовь не делится на кусочки, её хватает на всех. 💞"},
  {"q":["что такое стыд","почему бывает стыдно","мне стыдно","что делать если стыдно"],"a":"Стыдно бывает, когда кажется, что сделал что-то не так. Это чувство помогает замечать ошибки, но ошибаются все люди: можно извиниться, исправить и идти дальше. 🌱"},
  {"q":["почему я волнуюсь","почему бабочки в животе","почему трясутся руки от волнения","как не волноваться перед контрольной"],"a":"Когда волнуешься, тело выпускает адреналин и готовится к важному делу — поэтому стучит сердце, дрожат руки и «порхают бабочки» в животе. Это нормально, а успокоиться помогает медленное дыхание. 🦋"},
  {"q":["как успокоиться","что делать чтобы успокоиться","как быстро успокоиться","не могу успокоиться"],"a":"Попробуй медленно вдохнуть носом на счёт 4 и так же медленно выдохнуть ртом — повтори несколько раз. Ещё помогают глоток воды, объятия и разговор с близким. 🌬️"},
  {"q":["почему мы смеёмся","почему смех заразный","зачем человек смеётся","почему люди смеются"],"a":"Мы смеёмся, когда смешно или неожиданно, и смех помогает людям сблизиться. Он заразный, потому что мы невольно повторяем за другими, а ещё от смеха поднимается настроение. 😂"},
  {"q":["что такое счастье","как стать счастливым","как быть счастливым","что делает людей счастливыми"],"a":"Счастье — это чувство радости и спокойствия внутри. Его часто дарят простые вещи: время с семьёй и друзьями, любимое занятие, помощь другим, хороший сон и прогулки. 😊"},
  {"q":["почему мне одиноко","что делать если одиноко","мне одиноко","мне не с кем поговорить"],"a":"Одиноко бывает каждому, когда не хватает близкого общения. Попробуй позвонить другу или бабушке, записаться в кружок или просто рассказать родителям, как ты себя чувствуешь. А со мной тоже всегда можно поболтать! 🤗"},
  {"q":["как помириться с другом","я поссорился с другом","что делать если поругался с другом","как помириться после ссоры"],"a":"Сначала немного успокойтесь, а потом поговорите: скажи, что чувствуешь, выслушай друга, а если был неправ — извинись. Ссоры бывают даже у лучших друзей, главное — уметь мириться. 🤝"},
  {"q":["что делать если поругался с родителями","я поссорился с мамой","родители на меня злятся","как помириться с родителями"],"a":"Родители любят тебя, даже когда сердятся. Когда все успокоятся, подойди и поговори: расскажи о своих чувствах и извинись, если был неправ, — обычно после этого всем становится легче. 💛"},
  {"q":["плакать мальчикам нормально","мальчики не плачут","стыдно ли плакать","можно ли мальчикам плакать"],"a":"Конечно можно! Плакать — нормально для всех людей, и мальчиков, и девочек, и даже взрослых. Слёзы помогают выпустить сильные чувства, и после них часто становится легче. 💧"},
  {"q":["почему сердце колотится когда страшно","почему сердце стучит от страха","почему от страха быстро бьётся сердце","почему когда страшно сердце бьется"],"a":"При страхе тело выпускает адреналин, и сердце начинает быстрее гнать кровь к мышцам, чтобы ты был готов бежать. Когда опасность проходит, сердце снова успокаивается. 💓"},
  {"q":["что такое стресс","почему бывает стресс","у меня стресс","как справиться со стрессом"],"a":"Стресс — это реакция тела на что-то трудное или новое, например контрольную или соревнование. Немного стресса помогает собраться, а если его много — нужны отдых, сон и разговор с близкими. 🧘"},
  {"q":["не могу уснуть","почему не могу заснуть","что делать если не спится","как быстро уснуть"],"a":"Когда волнуешься, мысли крутятся и мешают уснуть. Расскажи о своих переживаниях родителям, отложи телефон, медленно подыши и представь какое-нибудь спокойное красивое место. 🌙"},
  {"q":["почему меняется настроение","почему плохое настроение","почему у меня нет настроения","отчего портится настроение"],"a":"Настроение зависит от многого: выспался ли ты, не голоден ли, не устал ли и что произошло за день. Голодный человек часто бывает злее — так что иногда помогает просто поесть и отдохнуть! 🙂"},
  {"q":["что такое эмпатия","как понять что чувствует другой","что такое сочувствие","как понять другого человека"],"a":"Эмпатия — это умение понять и почувствовать, что чувствует другой человек. Посмотри на его лицо, выслушай и представь себя на его месте — так рождаются доброта и настоящая дружба. 💗"},
  {"q":["зачем люди обнимаются","почему приятно обниматься","почему хочется обниматься","зачем нужны обнимашки"],"a":"Когда мы обнимаемся, мозг выделяет вещество окситоцин, и становится спокойно, тепло и безопасно. Только перед объятиями лучше спросить, хочет ли этого другой человек. 🤗"},
  {"q":["что такое гормоны счастья","как поднять настроение","от чего становится радостно","как стать веселее"],"a":"В мозге есть вещества, от которых нам хорошо: дофамин, серотонин, эндорфины и окситоцин. Их помогают «включить» движение, солнце, смех, объятия и радость от того, что у тебя что-то получилось. ☀️"},
  {"q":["что делать если проиграл","почему обидно проигрывать","я проиграл и мне обидно","как не расстраиваться из-за проигрыша"],"a":"Обидно бывает всем, даже чемпионам, — ведь они тоже много раз проигрывали, прежде чем научились побеждать. Сделай глубокий вдох, поздравь соперника и подумай, что получится лучше в следующий раз. 🏆"},
  {"q":["мне очень плохо","мне долго грустно","мне плохо и никто не понимает","не хочу ничего делать мне плохо"],"a":"Мне жаль, что тебе так тяжело. Обязательно расскажи взрослому, которому доверяешь, — маме, папе, учителю. Если плохо телу — что-то болит или тошнит, — скажи взрослым прямо сейчас. А ещё можно бесплатно и анонимно позвонить на Детский телефон доверия: 8-800-2000-122. Если ты в опасности — звони 112. Ты не один! 💛"},
  {"q":["почему я стесняюсь","как перестать стесняться","я стеснительный","что делать если стесняюсь"],"a":"Стесняются очень многие, и в этом нет ничего плохого. Начни с маленьких шагов — поздоровайся, улыбнись, задай вопрос, — и с каждым разом будет всё легче. 🌷"},
  {"q":["почему мы скучаем","почему я скучаю по маме","что делать если скучаешь по кому-то","я скучаю по другу"],"a":"Мы скучаем по тем, кто нам дорог, — значит, этот человек для тебя очень важен. Можно позвонить ему, написать письмо, нарисовать рисунок или посмотреть ваши общие фотографии. 💌"},
  {"q":["почему мы краснеем","почему краснеют щёки когда стыдно","почему я краснею","отчего человек краснеет"],"a":"Когда смущаешься, тело выпускает адреналин, сосуды на лице расширяются, к щекам приливает кровь — и они краснеют. Это нормально и быстро проходит. ☺️"},
  {"q":["почему небо голубое","почему небо синее","отчего небо голубого цвета","пачему небо голубое"],"a":"Солнечный свет состоит из всех цветов радуги. Воздух сильнее всего рассеивает синие и голубые лучи, и они разлетаются по всему небу — поэтому оно кажется голубым. 🌤️"},
  {"q":["почему закат красный","почему небо на закате оранжевое","почему солнце красное когда садится","почему вечером небо розовое"],"a":"Вечером солнечные лучи проходят через очень толстый слой воздуха. Синий свет по дороге рассеивается, а до нас доходят красные и оранжевые лучи — вот и получается красивый закат. 🌅"},
  {"q":["почему идёт дождь","откуда берётся дождь","почему идет дождик","как появляется дождь"],"a":"Солнце нагревает воду в морях, реках и лужах, и она превращается в невидимый пар. Пар поднимается, остывает и собирается в капельки — так получаются облака. Когда капли становятся слишком тяжёлыми, они падают вниз дождём. 🌧️"},
  {"q":["откуда берутся облака","из чего сделаны облака","что такое облако","облака из ваты?"],"a":"Облака состоят из крошечных капелек воды или кристалликов льда. Они такие маленькие и лёгкие, что держатся в воздухе и плывут по небу. ☁️"},
  {"q":["почему облака белые а тучи серые","почему тучи тёмные","почему туча черная","почему перед дождём небо темнеет"],"a":"Тонкие облака пропускают и рассеивают солнечный свет, поэтому они белые. В толстой туче очень много капель, и свет почти не проходит сквозь неё — поэтому снизу она кажется серой или тёмной. ⛈️"},
  {"q":["почему идёт снег","откуда берётся снег","как получается снег","почему зимой снег а не дождь"],"a":"Когда в облаке очень холодно, водяной пар превращается не в капли, а в ледяные кристаллики. Они растут, слипаются в снежинки и падают вниз. Если у земли тоже мороз, снежинки не тают — и идёт снег. ❄️"},
  {"q":["почему снежинки разные","почему у снежинки шесть лучиков","бывают ли одинаковые снежинки","почему снежинка шестиугольная"],"a":"Замерзая, частички воды складываются в шестиугольный узор, поэтому у снежинок обычно шесть лучей. Каждая снежинка летит своим путём через разный холод и влажность, поэтому найти две совсем одинаковые почти невозможно. ❄️"},
  {"q":["как появляется радуга","откуда берётся радуга","почему бывает радуга","почему радуга после дождя"],"a":"Радуга появляется, когда солнце светит сквозь капли дождя. Каждая капелька, как маленькая призма, раскладывает белый свет на цвета. Чтобы увидеть радугу, нужно стоять спиной к солнцу, а дождь должен быть впереди. 🌈"},
  {"q":["сколько цветов у радуги","какие цвета у радуги","сколько цветов в радуге и какие","как запомнить цвета радуги"],"a":"Обычно называют семь цветов: красный, оранжевый, жёлтый, зелёный, голубой, синий и фиолетовый. Запомнить их помогает фраза: «Каждый Охотник Желает Знать, Где Сидит Фазан». 🌈"},
  {"q":["что такое молния","откуда берётся молния","почему бывает молния","как появляется молния"],"a":"Молния — это огромная электрическая искра. В грозовой туче льдинки и капли трутся друг о друга и накапливают электричество, а потом оно разом проскакивает между тучами или в землю. ⚡"},
  {"q":["почему гремит гром","что такое гром","откуда берётся гром","почему гром такой громкий"],"a":"Молния мгновенно нагревает воздух вокруг себя так, что он становится в несколько раз горячее поверхности Солнца. Воздух резко расширяется, как при взрыве, и мы слышим грохот — это и есть гром. 🌩️"},
  {"q":["почему сначала молния а потом гром","почему гром слышно позже молнии","почему мы видим молнию раньше чем слышим гром","как узнать далеко ли гроза"],"a":"Свет летит очень быстро, а звук — гораздо медленнее, примерно 1 километр за 3 секунды. Посчитай секунды между вспышкой и громом и раздели на три — узнаешь, сколько километров до грозы. ⚡"},
  {"q":["что делать если гроза","как вести себя в грозу","опасна ли гроза","можно ли прятаться под деревом в грозу"],"a":"Да, гроза может быть опасной из-за молний. В грозу лучше быть в доме или в машине. Нельзя прятаться под деревьями (особенно под одиноким деревом), купаться и стоять в открытом поле. Если гроза застала на улице — скорее иди в укрытие и позови взрослых. ⚡"},
  {"q":["почему бывают времена года","почему зимой холодно а летом жарко","откуда берутся зима и лето","почему меняются времена года"],"a":"Земная ось немного наклонена. Пока Земля за год облетает Солнце, то одна, то другая половина планеты повёрнута к Солнцу сильнее: там лучи падают прямее и дни длиннее — наступает лето. А там, где лучи падают косо, — зима. 🌍"},
  {"q":["почему осенью листья желтеют","почему листья становятся жёлтыми и красными","почему листья меняют цвет осенью","почему листья жолтые осенью"],"a":"Летом в листьях много зелёного вещества — хлорофилла, и оно закрывает другие цвета. Осенью света меньше, хлорофилл разрушается, и становятся видны жёлтые и оранжевые краски, а у некоторых деревьев появляются ещё и красные. 🍁"},
  {"q":["почему листья опадают","зачем деревья сбрасывают листья","почему осенью падают листья","почему зимой на деревьях нет листьев"],"a":"Зимой земля замерзает, и дереву трудно доставать из неё воду, а через листья вода всё время испаряется. Чтобы не засохнуть и не сломаться под тяжестью снега, деревья сбрасывают листья и «засыпают» до весны. 🍂"},
  {"q":["почему ёлка зимой зелёная","почему ёлки не сбрасывают иголки","почему у сосны зимой иголки","почему елка всегда зеленая"],"a":"Иголки ёлки — это узкие листья, покрытые воском. Они почти не испаряют воду и не боятся мороза, поэтому остаются на ветках зимой. Каждая иголка живёт несколько лет, а потом незаметно сменяется новой. 🎄"},
  {"q":["почему море солёное","почему вода в море солёная","откуда в море соль","почему в океане соленая вода"],"a":"Реки миллионы лет вымывают из камней и земли немножко солей и несут их в море. Вода из моря испаряется, а соль остаётся, и её накапливается всё больше. Поэтому морская вода солёная, а речная — почти пресная. 🌊"},
  {"q":["можно ли пить морскую воду","почему нельзя пить воду из моря","что будет если попить морской воды"],"a":"Морскую воду пить нельзя: в ней так много соли, что организм тратит больше воды, чтобы от этой соли избавиться, чем получает. От неё только сильнее хочется пить. 💧"},
  {"q":["что такое приливы и отливы","почему вода в море то приходит то уходит","почему бывают приливы","откуда приливы"],"a":"Приливы и отливы создаёт в основном Луна. Она притягивает к себе воду в океане, и вода у берега то поднимается, то опускается — обычно два раза в сутки. 🌕"},
  {"q":["что такое вулкан","почему извергаются вулканы","откуда в вулкане лава","как работает вулкан"],"a":"Глубоко под землёй очень горячо. В некоторых местах камни там плавятся и превращаются в жидкую раскалённую магму. Иногда она находит трещину и вырывается наверх вместе с газами, пеплом и камнями — это извержение. Магма, вылившаяся наружу, называется лавой. 🌋"},
  {"q":["что такое землетрясение","почему бывают землетрясения","почему трясётся земля","откуда землетрясения"],"a":"Поверхность Земли состоит из огромных каменных плит, которые очень медленно двигаются. Иногда они цепляются друг за друга, а потом резко сдвигаются — и земля дрожит. 🌍"},
  {"q":["что такое цунами","откуда берётся цунами","почему бывает цунами"],"a":"Цунами — это огромная волна, которая появляется, когда под дном океана происходит землетрясение или извержение вулкана. Вода резко сдвигается, и волна мчится к берегу, вырастая в высоту. 🌊"},
  {"q":["откуда берутся горы","как появляются горы","почему бывают горы","как выросли горы"],"a":"Большинство гор появилось там, где огромные плиты земной коры сталкиваются и сминаются, как скатерть, если её сдвинуть. Это происходит очень медленно — миллионы лет. А некоторые горы — это вулканы. ⛰️"},
  {"q":["какая самая высокая гора","самая высокая гора в мире","как называется самая высокая гора","эверест какой высоты"],"a":"Самая высокая гора на Земле — Эверест (его ещё называют Джомолунгма) в Гималаях. Его высота — около 8849 метров над уровнем моря. 🏔️"},
  {"q":["почему на горах холодно","почему на вершине горы снег","почему наверху холоднее если ближе к солнцу","почему в горах снег летом"],"a":"Солнце греет в основном землю, а уже от земли нагревается воздух. Тёплый воздух поднимается вверх, расширяется и остывает, поэтому чем выше — тем холоднее: примерно на 6 градусов на каждый километр. А то, что вершина чуть ближе к Солнцу, ничего не меняет — до Солнца целых 150 миллионов километров! Поэтому на высоких горах снег лежит даже летом. 🏔️"},
  {"q":["какая самая длинная река","самая длинная река в мире","нил или амазонка что длиннее"],"a":"Обычно называют Нил в Африке — около 6650 километров. Но некоторые учёные считают, что Амазонка в Южной Америке чуть длиннее: всё зависит от того, где считать её начало. А самая полноводная река — точно Амазонка. 🏞️"},
  {"q":["какой самый большой океан","самый большой океан на земле","сколько океанов на земле","какие есть океаны"],"a":"Самый большой — Тихий океан, он больше, чем вся суша Земли вместе взятая. Сейчас чаще всего выделяют пять океанов: Тихий, Атлантический, Индийский, Северный Ледовитый и Южный (раньше считали четыре, без Южного). 🌊"},
  {"q":["какое самое глубокое место на земле","самое глубокое место в океане","что такое марианская впадина","какая глубина марианской впадины"],"a":"Самое глубокое место — Марианская впадина в Тихом океане. Её глубина почти 11 километров: если опустить туда Эверест, его вершина всё равно оказалась бы глубоко под водой. 🌊"},
  {"q":["какое самое большое озеро","самое глубокое озеро в мире","что такое байкал","чем знаменит байкал"],"a":"Самое большое по площади озеро — Каспийское море. А самое глубокое — Байкал в России: больше 1600 метров! В Байкале хранится примерно пятая часть всей пресной воды озёр и рек планеты. 💧"},
  {"q":["где самое холодное место на земле","какой самый сильный мороз был","где холоднее всего","самое холодное место в мире"],"a":"Самое холодное место — Антарктида. На российской станции «Восток» в 1983 году измерили −89,2 °C! А среди мест, где постоянно живут люди, одно из самых холодных — Оймякон в Якутии. 🥶"},
  {"q":["какая самая большая пустыня","самая большая пустыня в мире","сахара самая большая пустыня?","что такое пустыня"],"a":"Пустыня — это место, где почти не бывает дождей. Самая большая жаркая пустыня — Сахара в Африке. А если считать и холодные пустыни, то самая большая — Антарктида: осадков там тоже очень мало. 🏜️"},
  {"q":["откуда берётся ветер","почему дует ветер","что такое ветер","кто делает ветер"],"a":"Ветер — это движение воздуха. Солнце нагревает землю неравномерно: тёплый воздух поднимается вверх, а на его место устремляется прохладный. Это движение мы и чувствуем как ветер. 🌬️"},
  {"q":["что такое туман","откуда берётся туман","почему бывает туман","туман это облако?"],"a":"Туман — это облако, которое опустилось к самой земле. Когда воздух у земли остывает, водяной пар превращается в крошечные капельки, и они висят в воздухе белой дымкой. 🌫️"},
  {"q":["что такое роса","откуда берётся роса на траве","почему утром трава мокрая","почему утром роса"],"a":"Ночью трава и земля остывают. Водяной пар из воздуха касается холодных травинок и превращается в капельки — это роса. А если ночью мороз, вместо росы получается иней. 💧"},
  {"q":["почему бывает град","что такое град","откуда летом лёд с неба","почему летом идет град"],"a":"Град рождается в высоких грозовых тучах, где очень холодно даже летом. Капли там замерзают, сильный ветер подбрасывает их вверх-вниз, и на льдинке нарастают новые слои льда. Когда градина становится тяжёлой, она падает на землю. 🧊"},
  {"q":["что такое торнадо","что такое смерч","откуда берётся торнадо","почему бывает смерч"],"a":"Торнадо, или смерч, — это бешено вращающийся столб воздуха, который тянется от грозовой тучи до самой земли. Он появляется, когда сталкиваются тёплый влажный и холодный воздух. Ветер в нём бывает быстрее гоночной машины. 🌪️"},
  {"q":["что такое северное сияние","откуда берётся северное сияние","почему небо светится на севере","где можно увидеть северное сияние"],"a":"Солнце выбрасывает поток крошечных заряженных частиц. Магнитное поле Земли направляет их к полюсам, там они врезаются в воздух высоко над землёй и заставляют его светиться зелёным, розовым и фиолетовым. В России сияние можно увидеть на севере, например в Мурманске. ✨"},
  {"q":["почему лёд не тонет","почему лёд плавает в воде","почему айсберг не тонет","почему лед легче воды"],"a":"Когда вода замерзает, её частички выстраиваются просторнее, и лёд становится легче воды. Поэтому он плавает. У айсберга над водой видна только верхушка, а примерно девять десятых прячется под водой. 🧊"},
  {"q":["почему зимой идёт пар изо рта","почему на морозе пар когда дышишь","почему зимой видно дыхание"],"a":"В нашем дыхании есть тёплый невидимый водяной пар. На морозе он сразу остывает и превращается в крошечные капельки — получается маленькое облачко, как туман. ☁️"},
  {"q":["почему в африке жарко а на северном полюсе холодно","почему на полюсах холодно","почему возле экватора жарко","почему в арктике холодно"],"a":"Около экватора солнце стоит высоко и светит почти прямо, поэтому там жарко. На полюсах солнце поднимается низко, его лучи падают косо и греют гораздо слабее, а белый снег ещё и отражает свет. 🌍"},
  {"q":["почему трава зелёная","почему листья зелёные","почему растения зелёного цвета","почему трава зеленая а не синяя"],"a":"В листьях и траве есть зелёное вещество — хлорофилл. Оно поглощает красный и синий свет, чтобы делать для растения еду, а зелёный отражает. Поэтому мы и видим растения зелёными. 🌿"},
  {"q":["чем питаются растения","как растения едят","что такое фотосинтез","зачем растениям солнце"],"a":"Растения сами делают себе еду! Листья берут солнечный свет, углекислый газ из воздуха и воду из корней и превращают их в сахар. Это называется фотосинтез, а заодно растения выделяют кислород, которым мы дышим. ☀️"},
  {"q":["что нужно растению чтобы расти","как вырастить цветок","почему цветок вянет","почему растение засохло"],"a":"Растению нужны свет, вода, воздух, тепло и земля с питательными веществами. Если чего-то не хватает — например, воды или света, — растение вянет. Но и слишком много воды вредно: корни могут загнить. 🪴"},
  {"q":["откуда берётся кислород","кто делает кислород","почему деревья дают кислород","откуда кислород в воздухе"],"a":"Кислород выделяют растения во время фотосинтеза. Много его дают леса, а примерно половину кислорода Земли производят крошечные водоросли в океане. 🌳"},
  {"q":["как узнать сколько лет дереву","что такое годичные кольца","почему на пеньке кольца","сколько лет дереву по кольцам"],"a":"На спиле дерева видны кольца. Каждый год дерево нарастает на одно кольцо: светлая часть вырастает весной и в начале лета, тёмная — ближе к осени. Посчитай кольца — и узнаешь возраст! 🪵"},
  {"q":["какое самое высокое дерево","самое высокое дерево в мире","какой высоты бывают деревья","что такое секвойя"],"a":"Самое высокое дерево — секвойя в Калифорнии (США). Самая высокая из найденных достигает примерно 116 метров — это как дом в 35–40 этажей! 🌲"},
  {"q":["какое самое старое дерево","сколько лет живут деревья","самое старое дерево на земле","сколько живёт дуб"],"a":"Некоторые деревья живут невероятно долго. Одна сосна остистая в горах США растёт уже около 4800 лет! Дубы тоже долгожители — они живут сотни лет. 🌳"},
  {"q":["почему у кактуса колючки","зачем кактусу иголки","почему кактус колючий","как кактус живёт без воды"],"a":"Колючки кактуса — это видоизменённые листья. Через них почти не испаряется вода, и они защищают кактус от животных, которые хотели бы его съесть. А воду кактус запасает в своём толстом стебле. 🌵"},
  {"q":["почему цветы пахнут","зачем цветам запах","почему цветы яркие","зачем цветам яркие лепестки"],"a":"Яркие лепестки и запах нужны, чтобы приманить пчёл, бабочек и других опылителей. Насекомые пьют сладкий нектар и переносят пыльцу с цветка на цветок — после этого появляются семена и плоды. 🌸"},
  {"q":["откуда берутся семена","как появляются семена","как из семечка вырастает растение","что внутри семечка"],"a":"Семена появляются в цветке после того, как на него попадёт пыльца. Внутри семечка спрятан крошечный зародыш будущего растения и запас еды для него. Когда семечко попадает во влажную тёплую землю, оно прорастает. 🌱"},
  {"q":["почему одуванчик становится белым","почему одуванчик пушистый","зачем одуванчику пух","куда улетают пушинки одуванчика"],"a":"Когда жёлтый цветок отцветает, на его месте созревают семена. У каждого семечка есть пушистый «парашютик», и ветер разносит их далеко-далеко, чтобы выросли новые одуванчики. 🌼"},
  {"q":["почему подсолнух поворачивается к солнцу","правда ли подсолнух следит за солнцем","почему подсолнух так называется"],"a":"Молодые подсолнухи и правда днём поворачиваются за солнцем с востока на запад, а ночью возвращаются обратно. Когда подсолнух вырастает и зацветает, он останавливается и обычно смотрит на восток. А назвали его так потому, что он тянется к солнцу и сам похож на маленькое солнышко. 🌻"},
  {"q":["грибы это растения","гриб растение или животное","что такое грибы","грибы растения или нет"],"a":"Грибы — не растения и не животные, а отдельное царство живых существ. В отличие от растений, они не умеют делать себе еду из солнечного света. Настоящий гриб живёт под землёй тонкими ниточками — грибницей, а то, что мы собираем, — его плодовое тело. 🍄"},
  {"q":["какие грибы можно есть","как отличить ядовитый гриб","можно ли есть грибы из леса","мухомор ядовитый"],"a":"Многие грибы ядовиты, а некоторые очень похожи на съедобные, поэтому собирать и пробовать грибы без взрослых нельзя. Мухомор и бледная поганка — ядовитые! Если сомневаешься — не трогай и спроси взрослых. ⚠️"},
  {"q":["можно ли есть ягоды в лесу","какие ягоды ядовитые","как узнать ядовитая ли ягода"],"a":"Некоторые лесные ягоды очень ядовиты, например вороний глаз и волчье лыко. Поэтому есть незнакомые ягоды нельзя — сначала обязательно покажи их взрослым. ⚠️"},
  {"q":["почему крапива жжётся","почему крапива кусается","почему от крапивы чешется","зачем крапиве жгучие волоски"],"a":"Крапива покрыта крошечными волосками с острыми кончиками. Когда ты её касаешься, кончики обламываются, как иголочки, и впрыскивают в кожу едкий сок. Так крапива защищается от животных. 🌿"},
  {"q":["бывают ли растения которые едят насекомых","что такое венерина мухоловка","есть ли хищные растения","растения едят мух"],"a":"Да! Есть хищные растения: венерина мухоловка захлопывает листья, как ловушку, а росянка ловит насекомых на липкие капельки. Обычно они растут на бедной почве, и насекомые служат им «добавкой» к питанию. 🪴"},
  {"q":["какой самый большой цветок","самый большой цветок в мире","что такое раффлезия"],"a":"Самый большой одиночный цветок — раффлезия, она растёт в тропических лесах Юго-Восточной Азии. Её цветок бывает почти метр в диаметре и пахнет тухлым мясом, чтобы приманить мух! 🌺"},
  {"q":["почему у зебры полоски","зачем зебре полоски","зебра белая в черную полоску или черная в белую","почему зебра полосатая"],"a":"Учёные долго спорили, и сейчас главная версия такая: полоски отпугивают кусачих мух — им трудно сесть на полосатую шкуру. Возможно, они ещё помогают сбивать с толку хищников. А кожа у зебры под шерстью тёмная, поэтому учёные чаще говорят, что зебра чёрная в белую полоску. 🦓"},
  {"q":["почему кошки мурлыкают","зачем кошка мурчит","как кошка мурлычет","почему кот мурчит"],"a":"Кошки мурлыкают, когда им хорошо и спокойно, а котята так показывают маме, что всё в порядке. Иногда кошки мурлычут и когда им плохо — чтобы успокоить себя. Звук получается от быстрых движений мышц в горле. 🐱"},
  {"q":["сколько живут кошки","сколько лет живёт кот","сколько живут коты","скок живут кошки"],"a":"Домашние кошки обычно живут 12–18 лет, а некоторые — больше 20. Чтобы кошка жила долго, ей нужны хорошая еда, забота и визиты к ветеринару. 🐈"},
  {"q":["сколько живут собаки","сколько лет живёт собака","почему маленькие собаки живут дольше","сколько живут собачки"],"a":"Собаки обычно живут 10–13 лет. Маленькие породы часто живут дольше крупных — до 15 лет и больше. Учёные думают, что большие собаки очень быстро растут и поэтому раньше стареют. 🐕"},
  {"q":["почему собака виляет хвостом","зачем собаки машут хвостом","собака виляет хвостом значит рада?"],"a":"Хвостом собака «разговаривает». Чаще всего виляние значит радость, но иногда собака виляет хвостом, когда волнуется или насторожена. Поэтому смотри на всю собаку и не подходи к чужим собакам без разрешения хозяина. 🐶"},
  {"q":["почему у собаки мокрый нос","зачем собаке мокрый нос","почему нос у собаки холодный"],"a":"Мокрый нос помогает собаке лучше чувствовать запахи: к влажной поверхности лучше «прилипают» частички запаха. А ещё влага на носу немного охлаждает собаку в жару. 🐕"},
  {"q":["почему собаки так хорошо чуют запахи","во сколько раз нюх собаки лучше человека","как собака находит по запаху"],"a":"В носу у собаки сотни миллионов клеток, чувствующих запахи, а у человека — всего около 5–6 миллионов. Учёные считают, что нюх у собаки в тысячи раз острее нашего. Поэтому собаки могут найти человека по следу и учуять то, что мы совсем не замечаем. 🐕"},
  {"q":["почему кошки приземляются на лапы","почему кошка падает на лапы","кошка всегда падает на четыре лапы?"],"a":"У кошек очень гибкая спина и отличное чувство равновесия: в падении они быстро переворачиваются лапами вниз. Но падать им всё равно опасно, поэтому на окнах, где живут кошки, нужны защитные сетки. 🐈"},
  {"q":["видят ли кошки в темноте","почему у кошек светятся глаза","как кошки видят ночью","почему глаза у кота светятся в темноте"],"a":"В полной темноте кошки не видят, но при слабом свете — гораздо лучше нас. В глазах у них есть особый слой-«зеркальце», который отражает свет. Поэтому ночью кошачьи глаза и светятся, если на них попадает луч фонарика. 🐱"},
  {"q":["почему кошка трётся об ноги","зачем кот трётся о человека","почему кот бодается"],"a":"На мордочке у кошки есть железы с запахом. Когда кошка трётся о тебя, она оставляет свою метку: «Это мой человек!». Так она показывает дружбу и доверие. 🐈"},
  {"q":["какое самое сильное животное","кто самый сильный в мире животных","самое сильное животное на земле"],"a":"Смотря как считать. Самое сильное животное на суше — слон: он может поднять хоботом тяжёлое бревно. А если сравнивать с собственным весом, чемпионы — жуки: некоторые жуки-навозники могут тянуть груз больше чем в тысячу раз тяжелее себя! 🐘"},
  {"q":["какое самое быстрое животное","кто быстрее всех бегает","самое быстрое животное в мире","как быстро бегает гепард"],"a":"На суше быстрее всех гепард — на короткой дистанции он разгоняется примерно до 100 км/ч. А самая быстрая птица — сокол сапсан: падая с высоты на добычу, он развивает больше 300 км/ч! 🐆"},
  {"q":["какое самое большое животное","самое большое животное на земле","кто больше всех на свете","какой длины синий кит"],"a":"Самое большое животное на Земле — синий кит. Он бывает длиной около 30 метров и может весить больше 150 тонн — как два-три десятка слонов! Учёные считают, что даже самые большие динозавры были легче. 🐋"},
  {"q":["какое самое большое животное на суше","кто самый большой из зверей на суше","сколько весит слон"],"a":"Самое большое сухопутное животное — африканский саванный слон. Взрослый самец весит около 6 тонн и бывает выше 3 метров в плечах. 🐘"},
  {"q":["какое самое высокое животное","почему у жирафа длинная шея","какого роста жираф","зачем жирафу длинная шея"],"a":"Самое высокое животное — жираф, он бывает почти 6 метров ростом. Длинная шея помогает ему доставать листья с высоких деревьев, куда другие животные не дотянутся, а самцы ещё и меряются силой, толкаясь шеями. 🦒"},
  {"q":["какое самое маленькое животное","самая маленькая птица","самое маленькое животное в мире","кто самый маленький зверь"],"a":"Среди зверей одни из самых маленьких — летучая мышь-шмель и карликовая белозубка: они весят всего около 2 граммов. Самая маленькая птица — колибри-пчёлка, длиной около 5–6 сантиметров. А совсем крошечных существ можно увидеть только в микроскоп! 🐦"},
  {"q":["какое животное живёт дольше всех","сколько живут черепахи","кто живёт дольше всех на земле","самое долгоживущее животное"],"a":"Рекордсмен среди позвоночных — гренландская полярная акула: учёные считают, что она может жить около 400 лет. А среди всех животных рекорд у морского моллюска — исландской циприны: одна такая ракушка прожила 507 лет! Гигантские черепахи живут больше 150 лет, а черепаха Джонатан на острове Святой Елены перешагнула 190 лет. 🐢"},
  {"q":["зачем слону хобот","что слон делает хоботом","как слон пьёт","хобот это нос?"],"a":"Хобот — это нос и верхняя губа слона, сросшиеся вместе. Им слон дышит, нюхает, срывает ветки, обнимается и пьёт: набирает воду в хобот, а потом выливает её в рот. 🐘"},
  {"q":["зачем верблюду горб","что в горбу у верблюда","в горбу у верблюда вода?","почему верблюд долго не пьёт"],"a":"В горбу у верблюда не вода, а жир — запас еды на трудные дни. Без воды верблюд обходится долго, потому что очень экономно тратит влагу, а потом может выпить за раз 100 литров и больше. 🐫"},
  {"q":["почему птицы улетают на юг","зачем птицы улетают осенью","куда улетают птицы зимой","почему птицы улетают в теплые края"],"a":"Главная причина — еда. Зимой исчезают насекомые, замерзают водоёмы, и многим птицам нечего есть. Поэтому они улетают туда, где тепло и много корма, а весной возвращаются выводить птенцов. 🐦"},
  {"q":["как птицы находят дорогу","как птицы не теряются когда летят на юг","откуда птицы знают куда лететь"],"a":"Птицы ориентируются по солнцу, звёздам, рекам и горам, а ещё чувствуют магнитное поле Земли, будто у них внутри компас. Многие молодые птицы учатся дороге, летя вместе со взрослыми. 🧭"},
  {"q":["почему пингвины не летают","пингвин это птица?","почему пингвин не умеет летать","умеют ли пингвины летать"],"a":"Пингвины — птицы, но их крылья превратились в крепкие ласты. В воздухе они не летают, зато под водой будто летают — быстро плавают за рыбой. 🐧"},
  {"q":["где живут пингвины","белые медведи едят пингвинов","встречаются ли белые медведи и пингвины","живут ли пингвины на северном полюсе"],"a":"Белые медведи живут на севере, в Арктике, а почти все пингвины — в Южном полушарии: больше всего их в Антарктиде и на холодных островах вокруг неё. На Северном полюсе пингвинов нет. Белые медведи и пингвины живут на разных концах планеты, поэтому в природе не встречаются, и медведи пингвинов не едят! 🐧"},
  {"q":["почему белый медведь белый","какого цвета кожа у белого медведя","почему белому медведю не холодно"],"a":"Шерсть белого медведя на самом деле прозрачная и только кажется белой — так же, как снег. А кожа у него чёрная. От холода его защищают густой мех и толстый слой жира. ❄️"},
  {"q":["почему медведь спит зимой","зачем медведи впадают в спячку","что медведь ест зимой"],"a":"Зимой медведю почти нечего есть: нет ягод, травы и насекомых. Поэтому осенью он наедается и накапливает жир, а всю зиму спит в берлоге и ничего не ест — живёт за счёт этого запаса. Весной он просыпается худым и очень голодным. 🐻"},
  {"q":["почему ёжик сворачивается в клубок","зачем ежу иголки","сколько иголок у ежа","носят ли ежи яблоки на иголках"],"a":"Иголки защищают ежа: при опасности он сворачивается в колючий шарик, и хищнику трудно его схватить. У взрослого ежа примерно 5–7 тысяч иголок. А яблоки на спине ежи почти не носят — это скорее сказка, ведь едят они в основном жуков, червяков и улиток. 🦔"},
  {"q":["почему хамелеон меняет цвет","как хамелеон меняет цвет","зачем хамелеону менять цвет"],"a":"В коже хамелеона есть особые клетки с крошечными кристалликами. Меняя расстояние между ними, он меняет цвет. Чаще всего хамелеон так показывает настроение другим хамелеонам и согревается или охлаждается, а не только прячется. 🦎"},
  {"q":["как рыбы дышат под водой","чем дышат рыбы","зачем рыбам жабры","почему рыба не может жить без воды"],"a":"Рыбы дышат жабрами. Вода проходит через жабры, и они забирают из неё растворённый кислород. На воздухе жабры слипаются и пересыхают, поэтому рыба не может дышать без воды. 🐟"},
  {"q":["спят ли рыбы","как спят рыбы","почему рыбы спят с открытыми глазами"],"a":"Да, рыбы отдыхают: замирают у дна или среди водорослей и становятся менее внимательными. А с открытыми глазами они спят потому, что у большинства рыб просто нет век. 🐠"},
  {"q":["кит это рыба","дельфин рыба или нет","почему кит не рыба","чем дышит кит"],"a":"Киты и дельфины — не рыбы, а млекопитающие, как кошки и люди. Они дышат воздухом, всплывая к поверхности, и кормят детёнышей молоком. А фонтан у кита — это его выдох через дыхало. 🐬"},
  {"q":["кто сильнее акула или крокодил","акула или крокодил кто победит","крокодил против акулы"],"a":"На этот вопрос нет одного ответа: всё зависит от того, какая акула и какой крокодил и где они встретились. Гребнистый крокодил очень силён на мелководье, а большая акула — в открытом море. В природе они встречаются редко и обычно не дерутся. 🐊"},
  {"q":["кто сильнее лев или тигр","лев или тигр кто победит","тигр сильнее льва?"],"a":"Тигр обычно немного крупнее и тяжелее льва, поэтому многие считают его сильнее. Но точного ответа нет: в природе львы и тигры почти не встречаются — львы живут в основном в Африке, а тигры в Азии. 🐯"},
  {"q":["почему лев царь зверей","почему льва называют царём","зачем льву грива"],"a":"Льва называют царём зверей за величественный вид, пышную гриву и громкий рёв, который слышно за несколько километров. Грива показывает львицам и другим львам, какой самец сильный и здоровый: чем она гуще и темнее, тем лучше. 🦁"},
  {"q":["почему у тигра полоски","зачем тигру полоски","одинаковые ли полоски у тигров"],"a":"Полоски помогают тигру прятаться среди высокой травы и теней в лесу, чтобы незаметно подкрасться к добыче. Узор полосок у каждого тигра свой, как отпечатки пальцев у человека. 🐅"},
  {"q":["сколько ног у паука","паук это насекомое","сколько лап у паука","почему паук не насекомое"],"a":"У паука восемь ног, а у насекомых — шесть. Поэтому паук не насекомое, а паукообразное, как клещи и скорпионы. 🕷️"},
  {"q":["как пчёлы делают мёд","откуда берётся мёд","из чего пчёлы делают мёд","зачем пчелам мёд"],"a":"Пчёлы собирают с цветов сладкий нектар, приносят в улей, обрабатывают и складывают в восковые соты. Лишняя вода испаряется — пчёлы даже машут крылышками, как вентиляторами, — и получается мёд. Это их запас еды на зиму. 🍯"},
  {"q":["почему пчела умирает после укуса","пчела умирает когда ужалит","почему оса не умирает после укуса"],"a":"У медоносной пчелы жало с зазубринками. Когда она жалит человека, жало застревает в коже и отрывается вместе с частью брюшка, и пчела погибает. У осы жало гладкое, поэтому она может жалить много раз. 🐝"},
  {"q":["почему комары кусаются","зачем комары пьют кровь","все ли комары кусаются","почему комар пищит"],"a":"Кусают только самки комаров: кровь нужна им, чтобы отложить яйца. Самцы питаются нектаром цветов. А писк — это звук очень быстро машущих крылышек. 🦟"},
  {"q":["почему светлячки светятся","как светится светлячок","зачем светлячкам свет"],"a":"В брюшке у светлячка происходит особая химическая реакция, от которой появляется холодный свет. Своими огоньками светлячки подают сигналы друг другу, чтобы найти пару. ✨"},
  {"q":["как гусеница превращается в бабочку","откуда берутся бабочки","что такое куколка","бабочка была гусеницей?"],"a":"Из яичка вылупляется гусеница, она много ест и растёт. Потом она превращается в куколку, и внутри неё тело полностью перестраивается. Через какое-то время из куколки выбирается бабочка! 🦋"},
  {"q":["сколько живёт бабочка","правда что бабочки живут один день","сколько живут бабочки"],"a":"Большинство бабочек живут от нескольких дней до нескольких недель. А некоторые, например бабочки-монархи, которые улетают на зимовку, могут прожить несколько месяцев. Один день живут не бабочки, а подёнки. 🦋"},
  {"q":["почему муравьи такие сильные","сколько может поднять муравей","во сколько раз муравей сильнее себя"],"a":"Муравей может поднять груз в 10–50 раз тяжелее себя! Маленьким животным гораздо легче держать свой вес, поэтому сила их мышц по сравнению с телом кажется огромной. 🐜"},
  {"q":["почему совы не спят ночью","почему сова охотится ночью","как сова поворачивает голову","на сколько сова поворачивает голову"],"a":"Большинство сов — ночные охотники: они ловят мышей, которые выходят по ночам. У совы отличный слух и зрение в темноте. Глаза у неё почти не двигаются, зато голову она может повернуть примерно на 270 градусов! 🦉"},
  {"q":["почему фламинго розовые","почему фламинго розового цвета","фламинго рождаются розовыми?"],"a":"Фламинго едят маленьких рачков и водоросли с красящими веществами. Эти краски и окрашивают их перья в розовый цвет. Птенцы рождаются серыми и розовеют постепенно. 🦩"},
  {"q":["почему заяц зимой белый","почему заяц меняет шубку","зачем зайцу менять цвет"],"a":"Заяц-беляк осенью линяет и вместо серой шубки получает белую. На снегу белого зайца трудно заметить, и лисе или волку сложнее его поймать. Весной он снова становится серым. 🐇"},
  {"q":["сколько сердец у осьминога","сколько ног у осьминога","правда что у осьминога голубая кровь"],"a":"У осьминога три сердца, восемь щупалец и голубая кровь! Ещё осьминоги очень умные: умеют открывать банки, прятаться и менять цвет кожи. 🐙"},
  {"q":["какая самая ядовитая змея","самая опасная змея в мире","что делать если увидел змею"],"a":"Самый сильный яд — у пустынного тайпана из Австралии, но он живёт далеко от людей и кусает очень редко. Больше всего людей страдает от укусов гадюк и кобр в Азии и Африке. Змеи редко нападают первыми. Если увидел змею — не трогай её и спокойно отойди, а если кого-то укусила змея — сразу зови взрослых и вызывай врача по номеру 112. 🐍"},
  {"q":["как летучие мыши летают в темноте","почему летучие мыши висят вниз головой","летучая мышь слепая?"],"a":"Летучие мыши не слепые, а многие из них ещё и «видят» ушами: издают писк и слушают эхо, которое отражается от предметов. А висят вниз головой, потому что так им легко взлетать — просто разжать лапки и упасть в полёт. 🦇"},
  {"q":["когда жили динозавры","сколько лет назад жили динозавры","когда были динозавры","кагда жили динозавры"],"a":"Динозавры появились примерно 230 миллионов лет назад и жили на Земле очень долго — больше 160 миллионов лет. Вымерли они около 66 миллионов лет назад. 🦕"},
  {"q":["почему вымерли динозавры","куда делись динозавры","что случилось с динозаврами","почему динозавры исчезли"],"a":"Около 66 миллионов лет назад в Землю врезался огромный астероид — примерно 10 километров в поперечнике. Пыль закрыла солнце, стало холодно, растения погибли, и динозавры вымерли — выжили только предки птиц. Свою роль сыграли и сильные извержения вулканов. ☄️"},
  {"q":["жили ли люди вместе с динозаврами","видели ли люди динозавров","люди застали динозавров?"],"a":"Нет! Динозавры вымерли около 66 миллионов лет назад, а первые люди появились всего несколько миллионов лет назад. Так что ни один человек не видел живого тираннозавра или диплодока. Зато потомков динозавров — птиц — мы видим каждый день! 🦖"},
  {"q":["птицы потомки динозавров","правда что курица родственник динозавра","остались ли динозавры сейчас","живы ли динозавры"],"a":"Да, в каком-то смысле! Учёные считают птиц потомками небольших хищных динозавров. Так что воробей и курица — дальние родственники тираннозавра. А вот огромные динозавры вроде тираннозавра вымерли около 66 миллионов лет назад. 🐦"},
  {"q":["какой самый большой динозавр","самый большой динозавр в мире","какой длины был самый большой динозавр"],"a":"Самыми большими были длинношеие растительноядные динозавры — титанозавры, например аргентинозавр. По оценкам учёных, он был длиной около 30–35 метров. Точно сказать трудно, потому что обычно находят лишь часть костей. 🦕"},
  {"q":["какой самый страшный динозавр","кто такой тираннозавр","самый большой хищный динозавр","какого размера был тираннозавр"],"a":"Самый знаменитый хищник — тираннозавр: около 12 метров в длину, с зубами размером с банан. По оценкам учёных, ещё длиннее был спинозавр, который охотился на рыбу. 🦖"},
  {"q":["откуда мы знаем про динозавров","как узнали что были динозавры","как находят динозавров","что такое окаменелости"],"a":"Учёные-палеонтологи находят в земле окаменевшие кости, зубы, следы и даже яйца динозавров. По ним они узнают, как выглядели динозавры, чем питались и когда жили. 🦴"},
  {"q":["когда вымерли мамонты","мамонт это динозавр","кто такие мамонты","почему вымерли мамонты"],"a":"Мамонт — не динозавр, а древний родственник слона, покрытый густой шерстью. Мамонты жили вместе с древними людьми. Большинство из них исчезло около 10 тысяч лет назад: климат потеплел, их пастбища сократились, а ещё на них охотились люди. Последние мамонты дожили на острове Врангеля примерно до 4 тысяч лет назад. 🦣"},
  {"q":["сколько планет в солнечной системе","сколько всего планет","скока планет вокруг солнца","сколько планет есть"],"a":"В Солнечной системе 8 планет: Меркурий, Венера, Земля, Марс, Юпитер, Сатурн, Уран и Нептун. Наша Земля — третья по счёту от Солнца. 🪐"},
  {"q":["почему плутон не планета","плутон это планета","почему плутон больше не планета","плутон планета или нет"],"a":"В 2006 году астрономы договорились, что настоящая планета должна быть главной на своей орбите и «расчистить» её от других тел. Плутон маленький и делит свою орбиту с множеством ледяных объектов, поэтому теперь его называют карликовой планетой."},
  {"q":["почему луна не падает на землю","почему луна не падает","почему луна не улетает","как луна держится в небе"],"a":"Луна на самом деле всё время падает к Земле, но одновременно очень быстро летит вбок — примерно 1 километр в секунду. Поэтому она постоянно «промахивается» мимо Земли и кружит вокруг неё по орбите. 🌙"},
  {"q":["какое расстояние до луны","сколько километров до луны","как далеко луна","далеко ли до луны"],"a":"В среднем около 384 000 километров. Это почти как 10 раз объехать Землю по экватору, а свет пролетает такое расстояние всего за 1,3 секунды. 🌙"},
  {"q":["какое расстояние до солнца","сколько километров до солнца","как далеко солнце от земли","далеко ли до солнца"],"a":"Около 150 миллионов километров. Свет от Солнца летит до нас примерно 8 минут, а самолёт летел бы туда без остановок около 19 лет! ☀️"},
  {"q":["сколько звёзд на небе","сколько всего звёзд","сколько звезд во вселенной","сколько звезд можно увидеть"],"a":"В тёмную ночь вдали от города глазами можно увидеть примерно 2–3 тысячи звёзд сразу. В нашей галактике Млечный Путь их сотни миллиардов, а во всей Вселенной, по оценкам учёных, звёзд больше, чем песчинок на всех пляжах Земли. ✨"},
  {"q":["что больше солнце или земля","солнце больше земли","во сколько раз солнце больше земли","сколько земель поместится в солнце"],"a":"Солнце намного больше: оно шире Земли примерно в 109 раз, и внутрь него поместилось бы около 1,3 миллиона таких планет, как наша. Солнце кажется маленьким только потому, что оно очень далеко. ☀️"},
  {"q":["почему бывает день и ночь","почему день сменяется ночью","откуда берётся ночь","почему ночью темно"],"a":"Земля вращается вокруг своей оси и делает полный оборот примерно за 24 часа. Сторона, повёрнутая к Солнцу, освещена — там день, а противоположная сторона в тени — там ночь. 🌗"},
  {"q":["что такое чёрная дыра","откуда берутся черные дыры","как появляются чёрные дыры","черная дыра это что"],"a":"Чёрная дыра — это место в космосе, где вещество сжато так сильно, что его притяжение не выпускает наружу ничего, даже свет. Многие чёрные дыры появляются, когда очень большая звезда в конце жизни сжимается сама в себя. 🕳️"},
  {"q":["что такое гравитация","что такое притяжение","почему всё падает вниз","почему предметы падают"],"a":"Гравитация — это сила, с которой все предметы притягиваются друг к другу. Чем больше масса, тем сильнее притяжение, поэтому огромная Земля тянет к себе и мяч, и нас, и даже Луну. 🌍"},
  {"q":["почему мы не улетаем с земли","почему мы не падаем с земли","почему люди не улетают в космос","что нас держит на земле"],"a":"Нас держит гравитация — Земля всё время притягивает нас к своему центру. Поэтому, даже если сильно подпрыгнуть, мы сразу опускаемся обратно. 🌍"},
  {"q":["почему люди с другой стороны земли не падают","почему в австралии не падают вниз","почему люди внизу земли не падают","как люди ходят вверх ногами на другой стороне земли"],"a":"В космосе нет настоящих «верха» и «низа». Гравитация тянет всех к центру Земли, поэтому для каждого человека, где бы он ни стоял, «низ» — это под ногами. Жители Австралии стоят на земле так же уверенно, как и мы. 🌏"},
  {"q":["какая скорость света","как быстро летит свет","скорость света сколько","что быстрее всего на свете"],"a":"Свет летит со скоростью почти 300 000 километров в секунду. За одну секунду он мог бы облететь Землю примерно 7,5 раза — быстрее света ничего не бывает. ⚡"},
  {"q":["почему небо голубое","почему небо синее","отчего небо голубое","небо почему голубое"],"a":"Солнечный свет состоит из всех цветов радуги. Когда он проходит через воздух, синие и голубые лучи рассеиваются сильнее остальных и разлетаются по всему небу — поэтому, куда ни посмотришь, небо кажется голубым. 💙"},
  {"q":["почему закат красный","почему солнце красное на закате","почему небо розовое вечером","почему рассвет оранжевый"],"a":"Утром и вечером солнечный свет идёт к нам наискосок и проходит через гораздо более толстый слой воздуха. Синие лучи по дороге рассеиваются, а до нас доходят в основном красные и оранжевые. 🌅"},
  {"q":["солнце это звезда","солнце звезда или планета","что такое солнце","солнце это планета"],"a":"Солнце — это звезда, огромный раскалённый шар газа. Оно такая же звезда, как те, что мы видим ночью, просто находится намного ближе к нам. ☀️"},
  {"q":["какая самая большая планета","самая большая планета солнечной системы","какая планета больше всех","самая огромная планета"],"a":"Самая большая планета — Юпитер. Он шире Земли примерно в 11 раз, и внутрь него поместилось бы больше 1300 таких планет, как наша. 🪐"},
  {"q":["какая самая маленькая планета","самая маленькая планета солнечной системы","какая планета меньше всех","самая крошечная планета"],"a":"Самая маленькая планета — Меркурий. Он лишь ненамного больше нашей Луны и к тому же ближе всех планет к Солнцу."},
  {"q":["какая самая горячая планета","самая жаркая планета","на какой планете жарче всего","самая горячая планета это меркурий"],"a":"Самая горячая планета — Венера, хотя Меркурий ближе к Солнцу. У Венеры очень плотная атмосфера, которая держит тепло, как толстое одеяло, поэтому там около 460 градусов — жарче, чем в духовке. 🔥"},
  {"q":["какая самая холодная планета","самая холодная планета солнечной системы","на какой планете холоднее всего","самая морозная планета"],"a":"Дальше всех от Солнца находится Нептун, но рекорд холода принадлежит Урану: в его атмосфере измеряли около минус 224 градусов. На обеих этих планетах невероятно холодно. ❄️"},
  {"q":["какая самая далёкая планета","самая дальняя планета от солнца","какая планета последняя","самая далекая планета солнечной системы"],"a":"Самая далёкая планета — Нептун. Он примерно в 30 раз дальше от Солнца, чем Земля, и делает один оборот вокруг Солнца почти за 165 земных лет."},
  {"q":["есть ли жизнь на марсе","живут ли на марсе марсиане","есть ли на марсе инопланетяне","на марсе кто нибудь живёт"],"a":"Пока никакой жизни на Марсе не нашли. По Марсу ездят роботы-марсоходы и ищут её следы: учёные знают, что когда-то там текла вода, поэтому поиски продолжаются. 🔴"},
  {"q":["почему марс красный","почему марс называют красной планетой","марс почему красного цвета","почему марс оранжевый"],"a":"Поверхность Марса покрыта пылью и камнями, в которых много оксида железа — по сути, это ржавчина. Она и придаёт планете рыжевато-красный цвет. 🔴"},
  {"q":["можно ли жить на марсе","могут ли люди жить на марсе","можно ли переселиться на марс","полетят ли люди на марс"],"a":"Пока нет: на Марсе нечем дышать, очень холодно и нет защиты от опасного космического излучения. Учёные мечтают когда-нибудь построить там базы с герметичными домами, но люди на Марс ещё не летали. 🚀"},
  {"q":["сколько спутников у земли","сколько лун у земли","у земли одна луна","есть ли у земли другие спутники"],"a":"Естественный спутник у Земли один — Луна. А вот искусственных спутников, которые запустили люди, вокруг Земли летают тысячи. 🛰️"},
  {"q":["почему луна меняет форму","почему луна бывает полумесяцем","почему луна то круглая то нет","что такое фазы луны"],"a":"Луна всегда круглая, но Солнцем освещена только одна её половина. Пока Луна облетает Землю (примерно за месяц), мы видим освещённую часть под разным углом — то тонкий серп, то половинку, то полный круг. 🌒"},
  {"q":["почему луна светится","луна сама светит","откуда у луны свет","почему луна светит ночью"],"a":"Луна сама не светится — она отражает солнечный свет, как мяч, на который светят фонариком. 🌕"},
  {"q":["почему мы видим только одну сторону луны","почему луна всегда повёрнута одной стороной","что на обратной стороне луны","почему не видно обратную сторону луны"],"a":"Луна поворачивается вокруг своей оси ровно за то же время, за которое облетает Землю, — примерно за 27 дней. Поэтому к нам всегда обращена одна и та же её сторона. Обратную сторону, тоже покрытую кратерами, впервые сфотографировала советская станция «Луна-3» в 1959 году. 🌙"},
  {"q":["кто первый полетел в космос","кто первый человек в космосе","первый космонавт","кто такой гагарин"],"a":"Первым человеком в космосе стал Юрий Гагарин. 12 апреля 1961 года он облетел Землю на корабле «Восток-1» за 108 минут, поэтому 12 апреля — День космонавтики. 🚀"},
  {"q":["кто первый был на луне","кто первым ступил на луну","кто первый высадился на луну","первый человек на луне"],"a":"Первым на Луну ступил американский астронавт Нил Армстронг в июле 1969 года, во время полёта «Аполлон-11». Вместе с ним по Луне гулял Базз Олдрин. 🌙"},
  {"q":["кто первая женщина в космосе","первая женщина космонавт","кто такая терешкова","какая женщина первая полетела в космос"],"a":"Первой женщиной в космосе стала Валентина Терешкова. Она полетела 16 июня 1963 года на корабле «Восток-6» и провела на орбите почти трое суток. 🚀"},
  {"q":["какие животные первыми полетели в космос","какие собаки летали в космос","белка и стрелка кто это","собака лайка в космосе"],"a":"Первыми живыми существами в космосе были мушки-дрозофилы в 1947 году. В 1957 году собака Лайка первой из животных облетела Землю по орбите, но вернуть её тогда ещё не умели, а в 1960 году собаки Белка и Стрелка слетали на орбиту и благополучно вернулись домой. 🐕"},
  {"q":["какой был первый спутник","когда запустили первый спутник","первый искусственный спутник земли","кто запустил первый спутник"],"a":"Первый искусственный спутник Земли запустили в СССР 4 октября 1957 года. Это был металлический шар чуть больше полуметра в диаметре, который передавал по радио сигнал «бип-бип». 🛰️"},
  {"q":["сколько людей было на луне","сколько человек побывало на луне","сколько раз люди высаживались на луну","кто был на луне"],"a":"По Луне ходили 12 человек — все они американские астронавты из программы «Аполлон». С 1969 по 1972 год люди высаживались на Луну 6 раз, и каждый раз по Луне гуляли двое. Сейчас разные страны готовят новые полёты на Луну. 🌙"},
  {"q":["почему звёзды мерцают","почему звезды мигают","почему звезды переливаются","отчего звёзды мерцают"],"a":"Свет звезды проходит через воздух Земли, который всё время колышется. Этот воздух немного отклоняет лучи в разные стороны, и кажется, что звезда мигает. В открытом космосе звёзды не мерцают. ✨"},
  {"q":["что такое звезда","из чего сделаны звёзды","звезды это что","что такое звёзды на небе"],"a":"Звезда — это огромный раскалённый шар из газа, в основном водорода и гелия, который сам светит и греет. Наше Солнце тоже звезда, а остальные звёзды кажутся точками, потому что они очень далеко. ⭐"},
  {"q":["почему днём не видно звёзд","куда деваются звёзды днём","почему звезды видно только ночью","днем есть звезды"],"a":"Днём звёзды никуда не исчезают, просто Солнце так ярко освещает воздух, что слабый свет звёзд на этом фоне не виден. Если бы у Земли не было воздуха, небо было бы чёрным, и звёзды можно было бы увидеть даже днём. ⭐"},
  {"q":["что такое комета","откуда у кометы хвост","из чего сделана комета","комета это что"],"a":"Комета — это глыба льда, пыли и камней, которая летает вокруг Солнца. Когда она приближается к Солнцу, лёд испаряется, и у неё появляется длинный светящийся хвост. Самая знаменитая — комета Галлея, она возвращается примерно раз в 76 лет. ☄️"},
  {"q":["что такое падающая звезда","что такое метеорит","почему звёзды падают","падающая звезда это что"],"a":"«Падающая звезда» — вовсе не звезда, а маленький камешек или пылинка из космоса, которая на огромной скорости влетает в воздух и сгорает, оставляя яркий след. Это называется метеор, а если кусочек долетает до земли, его называют метеоритом. 🌠"},
  {"q":["что такое млечный путь","как называется наша галактика","почему млечный путь так называется","в какой галактике мы живём"],"a":"Млечный Путь — это наша галактика, огромное скопление из сотен миллиардов звёзд, и Солнце — одна из них. В тёмную ночь она видна как светлая полоса через всё небо, похожая на пролитое молоко. 🌌"},
  {"q":["что такое галактика","сколько галактик во вселенной","сколько всего галактик","галактика это что"],"a":"Галактика — это гигантский «звёздный город» из миллиардов звёзд, газа и пыли. Учёные считают, что во Вселенной сотни миллиардов галактик, а может быть, и больше. 🌌"},
  {"q":["сколько лет земле","сколько лет нашей планете","когда появилась земля","какой возраст земли"],"a":"Земле примерно 4,5 миллиарда лет. Солнце чуть старше — ему около 4,6 миллиарда лет. 🌍"},
  {"q":["сколько лет вселенной","когда появилась вселенная","какой возраст вселенной","вселенная сколько ей лет"],"a":"Учёные считают, что Вселенной около 13,8 миллиарда лет. Её возраст узнали, наблюдая, как разлетаются далёкие галактики, и изучая самый древний свет в космосе. 🌌"},
  {"q":["погаснет ли солнце","когда погаснет солнце","солнце может потухнуть","солнце когда нибудь потухнет"],"a":"Когда-нибудь да, но очень нескоро — примерно через 5 миллиардов лет. Тогда Солнце раздуется в красного гиганта, а потом сожмётся в маленькую остывающую звезду — белого карлика. Так что ни нам, ни нашим праправнукам волноваться не о чем. ☀️"},
  {"q":["почему в космосе невесомость","почему космонавты летают в станции","что такое невесомость","почему космонавты парят"],"a":"Станция и космонавты вместе с ней всё время свободно падают вокруг Земли, но летят вбок так быстро, что никогда на неё не падают. Когда падаешь вместе со всем вокруг, ничто ни на что не давит — это и есть невесомость. 👨‍🚀"},
  {"q":["можно ли дышать в космосе","есть ли в космосе воздух","почему в космосе нельзя дышать","зачем космонавтам скафандр"],"a":"Нет, в космосе нет воздуха, дышать там нечем. Поэтому космонавты выходят наружу только в скафандре — это маленький космический корабль в форме человека, с запасом воздуха и нужной температурой. 🧑‍🚀"},
  {"q":["холодно ли в космосе","какая температура в космосе","в космосе жарко или холодно","космос холодный"],"a":"Там и очень жарко, и очень холодно: на солнечной стороне предметы нагреваются больше чем до 100 градусов, а в тени остывают ниже минус 100. Пустой космос вдали от звёзд очень холодный — около минус 270 градусов. 🥶"},
  {"q":["есть ли звук в космосе","можно ли услышать звук в космосе","почему в космосе тихо","в космосе слышно"],"a":"В космосе полная тишина. Звук — это колебания воздуха или другого вещества, а в космосе воздуха нет, поэтому звуку не по чему передаваться. Космонавты разговаривают друг с другом по радио. 🔇"},
  {"q":["сколько лететь до луны","за сколько можно долететь до луны","сколько дней лететь до луны","как долго лететь на луну"],"a":"Кораблям «Аполлон» нужно было около 3 дней, чтобы долететь до Луны. Если бы туда вела дорога, на машине со скоростью 100 км/ч мы ехали бы без остановок примерно 5 месяцев. 🚀"},
  {"q":["сколько лететь до марса","за сколько можно долететь до марса","как долго лететь на марс","сколько месяцев лететь до марса"],"a":"Современные космические аппараты летят до Марса примерно 6–9 месяцев. Запускать их стараются примерно раз в 2 года, когда Земля и Марс удобнее всего расположены друг относительно друга. 🔴"},
  {"q":["что такое мкс","что такое международная космическая станция","как высоко летает мкс","мкс это что"],"a":"МКС — Международная космическая станция, где космонавты из разных стран живут и проводят опыты. Она летает примерно в 400 километрах над Землёй и облетает её всего за полтора часа — поэтому космонавты видят около 16 рассветов в сутки! 🛰️"},
  {"q":["как космонавты ходят в туалет","есть ли туалет в космосе","как в космосе ходят в туалет","туалет на мкс"],"a":"На станции есть специальный туалет, который работает как пылесос: поток воздуха засасывает всё внутрь, чтобы ничего не улетело. А воду на МКС даже очищают и используют снова. 🚽"},
  {"q":["как стать космонавтом","что нужно чтобы стать космонавтом","хочу быть космонавтом","как попасть в космос"],"a":"Космонавту нужно хорошо учиться (особенно математике, физике и английскому), быть здоровым и заниматься спортом. Обычно космонавтами становятся инженеры, лётчики или учёные, которые потом долго тренируются в центре подготовки. Всё начинается со школы — у тебя всё получится! 🚀"},
  {"q":["почему бывает зима и лето","почему меняются времена года","откуда берутся времена года","почему летом жарко а зимой холодно"],"a":"Земная ось немного наклонена, поэтому, пока Земля облетает Солнце, то северная, то южная половина планеты сильнее повёрнута к Солнцу. Где лучи падают прямее и день длиннее — там лето, а где наискосок — зима. Кстати, ближе всего к Солнцу Земля бывает как раз в начале января! ☀️"},
  {"q":["что такое високосный год","почему в феврале бывает 29 дней","сколько дней в году","зачем нужен високосный год"],"a":"Земля облетает Солнце примерно за 365 дней и 6 часов. Эти лишние 6 часов за 4 года складываются в целые сутки, поэтому почти каждые 4 года в феврале добавляют 29-е число — такой год называется високосным, и в нём 366 дней. 📅"},
  {"q":["что такое солнечное затмение","почему бывает затмение","почему солнце закрывается","что такое лунное затмение"],"a":"Солнечное затмение бывает, когда Луна проходит точно между Землёй и Солнцем и закрывает его собой, а лунное — когда Земля закрывает Луну своей тенью. Смотреть на солнечное затмение можно только через специальные защитные очки или фильтры, иначе можно сильно повредить глаза! 🌑"},
  {"q":["почему у сатурна кольца","из чего кольца сатурна","что за кольца у сатурна","у каких планет есть кольца"],"a":"Кольца Сатурна состоят из огромного множества кусочков льда и камня — от крошечных пылинок до глыб размером с дом. Учёные думают, что они могли появиться из обломков ледяного спутника или кометы, которые подлетели к Сатурну слишком близко и были разорваны его притяжением. Тонкие кольца есть ещё у Юпитера, Урана и Нептуна, но у Сатурна они самые яркие и красивые. 🪐"},
  {"q":["что такое солнечная система","из чего состоит солнечная система","солнечная система это что","что входит в солнечную систему"],"a":"Солнечная система — это Солнце и всё, что вокруг него вращается: 8 планет с их спутниками, карликовые планеты вроде Плутона, астероиды и кометы. Солнце в ней главное — в нём собрано больше 99% всего вещества системы. ☀️"},
  {"q":["что такое астероид","астероид это что","что такое пояс астероидов","упадёт ли астероид на землю"],"a":"Астероид — это каменная или металлическая глыба, которая летает вокруг Солнца; бывают размером с дом, а бывают в сотни километров. Больше всего их в поясе астероидов между Марсом и Юпитером. Учёные внимательно следят за крупными астероидами, и ни один из известных сейчас Земле не угрожает. 🪨"},
  {"q":["что такое световой год","световой год это сколько","сколько километров в световом году","световой год это время"],"a":"Световой год — это не время, а расстояние: столько свет пролетает за один год. Это около 9,5 триллиона километров, поэтому в световых годах удобно измерять огромные расстояния между звёздами. 🌟"},
  {"q":["какая ближайшая звезда","какая звезда ближе всего к земле","ближайшая к нам звезда","самая близкая звезда"],"a":"Самая близкая к нам звезда — Солнце! А следующая — Проксима Центавра, до неё около 4,2 светового года, то есть её свет летит к нам больше четырёх лет. ⭐"},
  {"q":["сколько весит земля","какая масса земли","сколько тонн весит земля","какой вес у земли"],"a":"Масса Земли — около 6 000 000 000 000 000 000 000 000 килограммов, то есть шестёрка и 24 нуля! Учёные вычислили это по тому, как сильно Земля притягивает предметы. 🌍"},
  {"q":["какой размер земли","какой диаметр земли","сколько километров вокруг земли","какая длина экватора"],"a":"Диаметр Земли — около 12 700 километров, а если обойти её по экватору, получится примерно 40 000 километров. Пешком без остановок такая прогулка заняла бы почти год. 🌍"},
  {"q":["почему земля круглая","земля плоская или круглая","почему земля шар","откуда известно что земля круглая"],"a":"Земля круглая, потому что гравитация тянет всё её вещество к центру одинаково со всех сторон, и получается шар. Это видно на фотографиях из космоса, а ещё во время лунного затмения тень Земли на Луне всегда круглая. 🌍"},
  {"q":["что внутри земли","что в центре земли","из чего состоит земля внутри","какое ядро у земли"],"a":"Земля устроена немного как яйцо: снаружи тонкая твёрдая кора, под ней толстая горячая мантия, а в центре — ядро из железа и никеля. Там больше 5000 градусов — почти как на поверхности Солнца. 🌋"},
  {"q":["почему мы не чувствуем как земля вертится","почему не кружится голова от вращения земли","земля крутится а мы не чувствуем","как быстро вертится земля"],"a":"Земля вращается очень плавно и равномерно, а мы вместе с воздухом и домами движемся вместе с ней — так же в плавно едущем поезде можно не заметить движения. А ведь на экваторе скорость вращения — около 1670 километров в час! 🌍"},
  {"q":["земля вращается вокруг солнца или солнце вокруг земли","что вокруг чего крутится земля или солнце","почему солнце ходит по небу","кто доказал что земля крутится вокруг солнца"],"a":"Земля вращается вокруг Солнца, а то, что Солнце «ходит» по небу, нам только кажется — на самом деле это Земля вертится вокруг своей оси. Первым подробно описал это польский учёный Николай Коперник почти 500 лет назад, а потом Галилей, Кеплер и Ньютон подтвердили это своими открытиями. ☀️"},
  {"q":["что такое большой взрыв","как появилась вселенная","откуда взялась вселенная","что было в начале вселенной"],"a":"Учёные считают, что около 13,8 миллиарда лет назад вся Вселенная была невероятно горячей и плотной, а потом начала быстро расширяться — это и называют Большим взрывом. Из того горячего вещества постепенно появились звёзды, галактики и планеты, а что было до этого, наука пока не знает. 💥"},
  {"q":["есть ли у вселенной конец","где заканчивается космос","что за краем вселенной","космос бесконечный"],"a":"Этого пока никто точно не знает. Мы можем видеть только ту часть Вселенной, откуда до нас успел долететь свет, а что дальше — одна из главных загадок науки. Может быть, именно ты её разгадаешь! 🌌"},
  {"q":["есть ли инопланетяне","существуют ли инопланетяне","есть ли жизнь на других планетах","мы одни во вселенной"],"a":"Пока жизнь нигде, кроме Земли, не найдена. Но во Вселенной так много звёзд и планет, что многие учёные считают: где-то она может быть, и её ищут с помощью телескопов и космических аппаратов. 👽"},
  {"q":["что будет если упасть в чёрную дыру","что внутри чёрной дыры","можно ли выбраться из черной дыры","что будет если попасть в черную дыру"],"a":"Выбраться обратно оттуда невозможно — даже свет не может. Рядом с чёрной дырой притяжение так сильно растягивает предметы, что они вытягиваются в длинную «макаронину», и учёные шутливо называют это спагеттификацией. А что внутри, пока никто не знает. 🕳️"},
  {"q":["какая температура солнца","насколько горячее солнце","сколько градусов на солнце","солнце горячее"],"a":"На поверхности Солнца около 5500 градусов, а в самом центре — примерно 15 миллионов градусов! Центр Солнца горячее пламени костра больше чем в десять тысяч раз. ☀️"},
  {"q":["почему солнце светит","почему солнце горит","как работает солнце","отчего солнце горячее"],"a":"Солнце не горит, как костёр. В его центре мельчайшие частицы водорода сталкиваются и сливаются в гелий — это термоядерная реакция, и при ней выделяется огромное количество света и тепла. ☀️"},
  {"q":["можно ли смотреть на солнце","почему нельзя смотреть на солнце","что будет если долго смотреть на солнце","смотреть на солнце вредно"],"a":"Нет, на Солнце смотреть нельзя — его яркий свет может навсегда повредить глаза, особенно если смотреть подолгу. И никогда не смотри на Солнце через бинокль, телескоп или фотоаппарат без специального солнечного фильтра! 😎"},
  {"q":["сколько я буду весить на луне","почему на луне легко прыгать","какая гравитация на луне","на луне весишь меньше"],"a":"На Луне притяжение примерно в 6 раз слабее, чем на Земле. Поэтому если ты весишь 30 килограммов, на Луне будешь чувствовать себя так, будто весишь всего 5, и сможешь прыгать гораздо выше! 🌙"},
  {"q":["почему на луне нет воздуха","есть ли на луне воздух","почему на луне нет атмосферы","можно ли дышать на луне"],"a":"Луна маленькая, и её притяжение слишком слабое, чтобы удержать воздух, — газы за миллиарды лет просто улетели в космос. Поэтому на Луне нечем дышать, а небо там чёрное даже днём. 🌑"},
  {"q":["как летает ракета","почему ракета летит","как ракета взлетает","почему ракета летит вверх"],"a":"Ракета с огромной силой выбрасывает назад раскалённые газы из двигателей, а они толкают её вперёд. Это как надутый шарик, который отпустили: воздух вылетает в одну сторону, а шарик летит в другую. 🚀"},
  {"q":["что такое полярная звезда","как найти полярную звезду","почему полярная звезда показывает север","где находится полярная звезда"],"a":"Полярная звезда находится почти точно над Северным полюсом, поэтому всю ночь стоит на одном месте, а остальные звёзды словно кружат вокруг неё. Если встать к ней лицом, впереди будет север, а найти её помогает ковш Большой Медведицы. ⭐"},
  {"q":["что такое созвездие","сколько всего созвездий","что такое большая медведица","как называются созвездия"],"a":"Созвездие — это участок неба с группой звёзд, которые люди издавна соединяли в воображаемые фигуры. Всего на небе 88 созвездий, например Орион, Кассиопея, Лебедь, Лев и Большая Медведица. Самое известное у нас — Большая Медведица: семь её ярких звёзд складываются в ковш. 🌌"},
  {"q":["какая самая яркая звезда","самая яркая звезда на небе","какая звезда светит ярче всех","самая яркая звезда ночью"],"a":"Самая яркая звезда ночного неба — Сириус. Но ещё ярче Сириуса часто сияет вовсе не звезда, а планета Венера — её даже называют «утренней» или «вечерней звездой». ✨"},
  {"q":["какие планеты можно увидеть без телескопа","можно ли увидеть планеты на небе","как отличить планету от звезды","какие планеты видно глазами"],"a":"Без телескопа можно увидеть пять планет: Меркурий, Венеру, Марс, Юпитер и Сатурн. Отличить планету от звезды помогает подсказка: планеты обычно светят ровно и почти не мерцают. 🔭"},
  {"q":["кто открыл гравитацию","кто придумал закон всемирного тяготения","кому упало яблоко на голову","кто такой ньютон"],"a":"Закон всемирного тяготения открыл английский учёный Исаак Ньютон больше 300 лет назад. Сам Ньютон рассказывал, что задумался о притяжении, глядя на падающее яблоко, а вот то, что яблоко упало ему прямо на голову, — скорее всего, придумали позже. 🍎"},
  {"q":["можно ли встать на юпитер","есть ли у юпитера поверхность","из чего состоит юпитер","можно ли приземлиться на юпитер"],"a":"Нет, у Юпитера нет твёрдой поверхности — это газовый гигант, состоящий в основном из водорода и гелия. Корабль просто погружался бы всё глубже в его облака, пока его не раздавило бы огромным давлением. 🪐"},
  {"q":["какая самая высокая гора в солнечной системе","самая большая гора в космосе","что такое гора олимп на марсе","самый большой вулкан в солнечной системе"],"a":"Самая высокая гора на планетах Солнечной системы — вулкан Олимп на Марсе. Его высота около 22 километров — это примерно в два с половиной раза выше нашего Эвереста. Это ещё и самый высокий из известных вулканов. 🌋"},
  {"q":["на какой планете день длиннее года","сколько длится день на венере","правда что на венере день длиннее года","как медленно вертится венера"],"a":"Это Венера! Один оборот вокруг своей оси она делает за 243 земных дня, а вокруг Солнца облетает всего за 225 дней. К тому же Венера крутится в обратную сторону, поэтому Солнце там восходит на западе. 🌞"},
  {"q":["почему сначала молния а потом гром","почему гром слышно позже молнии","как узнать далеко ли гроза","почему гром после молнии"],"a":"Свет долетает до нас почти мгновенно, а звук гораздо медленнее — около 340 метров в секунду. Посчитай секунды между вспышкой и громом и раздели на 3 — получишь, сколько примерно километров до грозы. ⛈️"},
  {"q":["какая скорость звука","как быстро летит звук","скорость звука сколько","что быстрее звук или свет"],"a":"В воздухе звук пролетает около 340 метров в секунду — это примерно 1200 километров в час. А свет быстрее звука почти в миллион раз! 🔊"},
  {"q":["как появляется радуга","почему бывает радуга","сколько цветов у радуги","откуда берётся радуга"],"a":"Радуга появляется, когда солнечный свет проходит через капли дождя: капли преломляют его и раскладывают на цвета. Обычно в ней выделяют 7 цветов, а запомнить их порядок помогает фраза «Каждый Охотник Желает Знать, Где Сидит Фазан». 🌈"},
  {"q":["почему лёд не тонет","почему лед плавает","почему лёд легче воды","почему лед на поверхности воды"],"a":"Когда вода замерзает, её частички выстраиваются в «решётку» с пустотами, и лёд становится немного легче такого же объёма воды. Поэтому лёд плавает, реки зимой замерзают сверху, а рыбы спокойно живут подо льдом. 🧊"},
  {"q":["почему корабль не тонет","почему железный корабль плавает","почему тяжелый корабль не тонет","почему лодка не тонет"],"a":"Вода выталкивает вверх всё, что в неё погружено, — это называется выталкивающей, или архимедовой, силой. Корабль внутри полый и вытесняет очень много воды, поэтому вода держит его, хотя он сделан из железа. 🚢"},
  {"q":["почему самолёт летает","как самолёт держится в воздухе","почему самолет не падает","как летает самолёт"],"a":"Двигатели толкают самолёт вперёд, а крылья устроены так, что быстро обтекающий их воздух создаёт подъёмную силу, направленную вверх. Пока самолёт летит достаточно быстро, эта сила держит его в воздухе. ✈️"},
  {"q":["что такое молния","откуда берётся молния","почему бывает молния","как появляется молния"],"a":"Молния — это гигантская электрическая искра. В грозовой туче капли и льдинки сталкиваются друг с другом и накапливают электричество, а потом оно разом проскакивает в землю, в другую тучу или прямо внутри тучи. В грозу нельзя стоять под одиноким деревом и купаться — лучше переждать в доме. ⚡"},
  {"q":["что тяжелее килограмм пуха или килограмм железа","что тяжелее кг ваты или кг железа","килограмм пуха или килограмм гвоздей что тяжелее","что тяжелее килограмм ваты или килограмм кирпичей"],"a":"Они весят одинаково — ведь это по одному килограмму! Просто килограмм пуха занимает гораздо больше места, поэтому кажется лёгким. Это известная загадка-ловушка. 😉"},
  {"q":["что падает быстрее тяжёлое или лёгкое","что быстрее упадёт молоток или перо","правда что тяжелые предметы падают быстрее","почему перо падает медленно"],"a":"Если бы не было воздуха, всё падало бы одинаково быстро! Перо падает медленно только потому, что ему мешает воздух: астронавт на Луне, где воздуха нет, уронил молоток и перо — и они упали одновременно. 🪶"},
  {"q":["что такое атом","из чего всё состоит","что такое атомы","из чего сделано всё вокруг"],"a":"Атомы — это крошечные частички, из которых состоит всё вокруг: вода, воздух, камни и мы сами. Они такие маленькие, что в одной капле воды их больше, чем звёзд в нашей галактике. ⚛️"},
  {"q":["почему магнит притягивает","как работает магнит","почему магнит притягивает железо","что такое магнит"],"a":"Вокруг магнита есть невидимое магнитное поле, которое притягивает железо, никель и некоторые другие металлы. Наша Земля тоже огромный магнит — поэтому стрелка компаса показывает на север. 🧲"},
  {"q":["какое самое большое число","самое большое число в мире","какое число самое большое","есть ли самое большое число"],"a":"Самого большого числа не существует! Какое бы огромное число ты ни придумал, к нему всегда можно прибавить 1 и получить ещё больше. ♾️"},
  {"q":["что такое бесконечность","бесконечность это число","сколько будет бесконечность плюс один","что такое знак бесконечности"],"a":"Бесконечность — это не обычное число, а идея о том, что что-то никогда не кончается, как ряд чисел 1, 2, 3 и так далее. Её обозначают знаком ∞, похожим на лежащую восьмёрку, и если к бесконечности прибавить 1, всё равно получится бесконечность. ♾️"},
  {"q":["зачем нужно умножение","зачем умножать","что такое умножение","почему умножение а не сложение"],"a":"Умножение — это быстрый способ сложить одинаковые числа. Например, если в 5 коробках по 6 конфет, можно сложить 6+6+6+6+6, а можно сразу умножить 5 × 6 = 30 — так гораздо быстрее! 🍬"},
  {"q":["почему нельзя делить на ноль","что будет если поделить на ноль","сколько будет разделить на 0","можно ли делить на ноль"],"a":"Разделить 6 на 0 — значит найти число, которое при умножении на 0 даст 6. Но любое число, умноженное на ноль, даёт ноль, поэтому такого числа нет, и на ноль делить нельзя. 🚫"},
  {"q":["что такое гугол","сколько нулей в гуголе","гугол это сколько","какое число называется гугол"],"a":"Гугол — это единица со 100 нулями. Это название придумал девятилетний племянник американского математика, а имя компании Google произошло как раз от слова «гугол». 🔢"},
  {"q":["сколько нулей в миллионе","сколько нулей в миллиарде","сколько нулей в триллионе","что больше миллиард или миллион"],"a":"В миллионе 6 нулей (1 000 000), в миллиарде — 9, а в триллионе — 12. Каждое следующее название в 1000 раз больше предыдущего, поэтому миллиард — это тысяча миллионов. 🔢"},
  {"q":["что такое число пи","чему равно пи","сколько цифр в числе пи","пи это сколько"],"a":"Число π (пи) показывает, во сколько раз длина любой окружности больше её диаметра, и равно примерно 3,14. Его цифры после запятой никогда не кончаются и не повторяются по порядку, а 14 марта (3.14) многие отмечают День числа пи! 🥧"},
  {"q":["кто придумал ноль","когда появился ноль","зачем нужен ноль","ноль это число"],"a":"Ноль как настоящее число придумали математики Древней Индии больше тысячи лет назад. Он очень важен: благодаря нулю мы можем записать и 5, и 50, и 500 одной цифрой с нулями. 0️⃣"},
  {"q":["что такое отрицательные числа","бывают ли числа меньше нуля","что такое минусовые числа","что меньше нуля"],"a":"Отрицательные числа — это числа меньше нуля, их пишут со знаком минус: −1, −5, −100. Ты встречаешь их на градуснике зимой: −10 градусов значит на 10 градусов холоднее нуля. 🌡️"},
  {"q":["что такое простое число","какие числа простые","простые числа это какие","сколько всего простых чисел"],"a":"Простое число делится без остатка только на 1 и на само себя: 2, 3, 5, 7, 11, 13 и так далее. Число 2 — единственное чётное простое число, а 1 простым не считается. Простых чисел бесконечно много — это доказали ещё в Древней Греции. 🔢"},
  {"q":["какое самое маленькое число","самое маленькое число в мире","есть ли самое маленькое число","какое число меньше всех"],"a":"Самого маленького числа нет: можно уходить в минус бесконечно — −1000, −1 000 000 и ещё меньше. А вот самое маленькое натуральное число, с которого мы начинаем считать, — это 1. 🔢"},
  {"q":["почему в минуте 60 секунд","почему в часе 60 минут","кто придумал что в часе 60 минут","почему не 100 минут в часе"],"a":"Это досталось нам от древних вавилонян, которые очень любили считать шестидесятками. Число 60 удобное: оно делится на 2, 3, 4, 5, 6, 10, 12, 15, 20 и 30, поэтому час легко делить на половинки, трети и четверти. ⏰"},
  {"q":["сколько будет 2+2*2","2 плюс 2 умножить на 2","два плюс два умножить на два","почему 2+2*2 равно 6"],"a":"Будет 6! Сначала выполняют умножение, а потом сложение: 2 × 2 = 4, потом 2 + 4 = 6. Если нужно сначала сложить, ставят скобки: (2 + 2) × 2 = 8. ✏️"},
  {"q":["что такое римские цифры","как писать римскими цифрами","как читать римские цифры","римские цифры как понять"],"a":"Римские цифры — это буквы: I = 1, V = 5, X = 10, L = 50, C = 100, D = 500, M = 1000. Если меньшая цифра стоит перед большей, её вычитают (IV = 4), а если после — прибавляют (VI = 6). 🏛️"},
  {"q":["кто придумал цифры","откуда взялись цифры","почему цифры называются арабскими","кто изобрёл цифры"],"a":"Цифры от 0 до 9, которыми мы пишем, придумали в Древней Индии. В Европу они попали через арабских учёных, поэтому их и называют арабскими. 🔢"},
  {"q":["что такое процент","что такое проценты","50 процентов это сколько","как понять проценты"],"a":"Процент — это одна сотая часть чего-нибудь: 100% — это всё целиком, 50% — половина, а 25% — четверть. Например, если зарядка телефона 50%, значит, он заряжен наполовину. 🔋"},
  {"q":["как быстро выучить таблицу умножения","как запомнить таблицу умножения","как умножать на 9 на пальцах","не могу выучить таблицу умножения"],"a":"Учи понемногу и повторяй каждый день, начиная с лёгкого: на 1, 2, 5 и 10. От перестановки множителей результат не меняется (3 × 7 = 7 × 3), значит, учить нужно почти вдвое меньше. А на 9 можно умножать на пальцах: загни палец с нужным номером — слева останутся десятки, справа единицы (9 × 3: 2 и 7, то есть 27). ✋"},
  {"q":["что такое числа фибоначчи","что такое последовательность фибоначчи","фибоначчи это что","числа фибоначчи в природе"],"a":"Это ряд, где каждое число равно сумме двух предыдущих: 1, 1, 2, 3, 5, 8, 13, 21 и так далее. Удивительно, но такие числа часто встречаются в природе — например, в спиралях семечек подсолнуха и чешуек шишки. 🌻"},
  {"q":["зачем нужна математика","зачем учить математику","почему математика важна","где пригодится математика"],"a":"Математика нужна почти везде: чтобы считать деньги в магазине, готовить по рецепту, строить дома, делать игры и запускать ракеты в космос. А ещё она учит думать логично и решать сложные задачи. 🧠"},
  {"q":["как летает самолёт","почему самолёт не падает","как самолет держится в воздухе","почему самолет летает он же тяжелый"],"a":"У самолёта особые крылья: когда он быстро мчится, воздух обтекает крыло так, что снизу давление больше, чем сверху, — получается подъёмная сила, она и держит самолёт. А вперёд его тянут мощные двигатели. ✈️"},
  {"q":["как работает мобильный телефон","как работает телефон","как телефон звонит другому человеку","как голос передается по телефону"],"a":"Телефон превращает твой голос в радиосигнал и отправляет его на ближайшую вышку сотовой связи. Дальше по сети сигнал доходит до телефона друга, и тот превращает его обратно в звук. 📱"},
  {"q":["как работает интернет","что такое интернет","откуда берется интернет","как работает инет"],"a":"Интернет — это миллионы компьютеров по всему миру, соединённых проводами, кабелями по дну океанов, радиосигналами и спутниками. Информация разбивается на маленькие кусочки-пакеты, они мчатся по этой сети и собираются у тебя на экране. 🌐"},
  {"q":["как работает компьютер","как устроен компьютер","как компьютер думает","что внутри компьютера"],"a":"Главная часть компьютера — процессор: он выполняет миллиарды простых команд в секунду. Все данные — картинки, игры, музыка — хранятся в виде нулей и единиц, а память помогает всё это запоминать. 💻"},
  {"q":["что такое искусственный интеллект","как работает ии","что такое нейросеть","как работает искуственный интелект"],"a":"Искусственный интеллект (ИИ) — это программа, которая учится на огромном количестве примеров и находит в них закономерности. Например, посмотрев миллионы фото кошек, нейросеть научится узнавать кошку на новой картинке. 🤖"},
  {"q":["может ли ии думать как человек","у ии есть чувства","искусственный интеллект умнее человека","робот может думать"],"a":"Не совсем. В некоторых делах — например, в шахматах или быстрых вычислениях — ИИ уже сильнее человека. Но у него нет чувств, и мир он понимает не так, как люди. Это мощный помощник, а мечтать, сопереживать и дружить по-настоящему умеют люди. 🙂"},
  {"q":["как работает wi-fi","что такое вайфай","как работает вай фай","как интернет летает по воздуху"],"a":"Wi-Fi — это беспроводная связь: роутер получает интернет по кабелю и передаёт его по воздуху с помощью радиоволн. Телефон или ноутбук ловит эти волны, как радиоприёмник, только вместо музыки — данные. 📶"},
  {"q":["как работает навигатор","как работает gps","как телефон знает где я","как работает джипиэс"],"a":"Высоко над Землёй летают спутники навигации, и каждый постоянно посылает сигнал с точным временем. Телефон ловит сигналы сразу от нескольких спутников и по разнице во времени вычисляет, где ты находишься (у России есть своя система — ГЛОНАСС, у США — GPS). 🛰️"},
  {"q":["как летит ракета","как работает ракета","почему ракета летит вверх","как ракета взлетает в космос"],"a":"В ракете сгорает топливо, и раскалённые газы с огромной силой вырываются из сопла вниз, а ракету по закону «действие равно противодействию» толкает в обратную сторону — вверх. Поэтому ракета может лететь даже в космосе, где нет воздуха. 🚀"},
  {"q":["почему спутник не падает","почему спутники не падают на землю","как спутник держится в космосе","почему мкс не падает"],"a":"Спутник на самом деле всё время падает к Земле, но при этом летит вбок с огромной скоростью — у МКС это почти 8 километров в секунду. Пока он падает, Земля из-за своей округлости «уходит» из-под него, и спутник кружит вокруг неё. 🛰️"},
  {"q":["почему корабль не тонет","почему железный корабль не тонет","как корабль плавает","почему корабли не тонут они же тяжелые"],"a":"Корабль широкий и пустой внутри, поэтому вытесняет очень много воды. Вода выталкивает его вверх с силой, равной весу вытесненной воды, — это сила Архимеда. Пока эта сила не меньше веса корабля, он держится на плаву. 🚢"},
  {"q":["как работает холодильник","почему в холодильнике холодно","как холодильник охлаждает","откуда холод в холодильнике"],"a":"По трубкам холодильника бегает специальное вещество — хладагент. Внутри холодильника оно испаряется и забирает тепло у продуктов, а компрессор сжимает его и выводит тепло наружу. Поэтому сзади холодильник бывает тёплым! ❄️"},
  {"q":["как работает микроволновка","как микроволновка греет еду","почему микроволновка нагревает","как работает микроволновая печь"],"a":"Микроволновка излучает невидимые микроволны. Они заставляют молекулы воды в еде очень быстро колебаться, и от этого еда нагревается. Только никогда не клади туда металл и фольгу — будут искры! ⚡"},
  {"q":["откуда берется электричество","откуда электричество в розетке","как электричество попадает в дом","кто делает электричество"],"a":"Электричество вырабатывают на электростанциях: вода, ветер или пар крутят огромные генераторы, а солнечные панели превращают в ток солнечный свет. По проводам ток бежит в города и попадает в розетку. В розетку ничего не засовывай — это опасно! ⚡"},
  {"q":["как работает батарейка","что внутри батарейки","откуда в батарейке энергия","почему батарейка садится"],"a":"Внутри батарейки есть вещества, которые вступают в химическую реакцию, и из-за этого по проводам бежит электрический ток. Когда вещества израсходуются, батарейка садится. Аккумулятор в телефоне можно зарядить снова, а старые батарейки сдают в специальный пункт сбора. 🔋"},
  {"q":["как летает вертолёт","как работает вертолет","как вертолет держится в воздухе","почему вертолет летает"],"a":"Большой винт вертолёта — это вращающиеся крылья: крутясь, они отбрасывают воздух вниз и поднимают машину вверх, а маленький хвостовой винт не даёт вертолёту крутиться вокруг себя. Первый удачный вертолёт такой схемы построил Игорь Сикорский, уехавший из России в США, — он взлетел в 1939 году. 🚁"},
  {"q":["что такое робот","как работает робот","роботы живые","кто такие роботы"],"a":"Робот — это машина, которая выполняет действия по программе: датчики помогают ей «видеть» и «чувствовать», а моторы — двигаться. Роботы не живые, но они собирают машины на заводах, пылесосят квартиры и даже исследуют Марс. 🤖"},
  {"q":["как стать программистом","что такое программирование","как научиться программировать","с чего начать программировать"],"a":"Программирование — это написание инструкций для компьютера на специальном языке. Начать можно со Scratch, где программы собирают из цветных блоков, а потом перейти на Python. Главное — пробовать, ошибаться и придумывать свои маленькие проекты! 👩‍💻"},
  {"q":["как защититься в интернете","какой пароль придумать","как безопасно сидеть в интернете","можно ли говорить пароль"],"a":"Никому не говори свои пароли, адрес и номер телефона, даже если в сети просят очень вежливо. Придумывай длинные пароли, не открывай подозрительные ссылки, а если что-то пугает или смущает — сразу расскажи родителям. 🔒"},
  {"q":["кто изобрел лампочку","кто придумал лампочку","кто изобрёл электрическую лампу","кто придумал лампу накаливания"],"a":"Над лампочкой трудились многие изобретатели. Русский инженер Александр Лодыгин получил патент на лампу накаливания в 1874 году, а Томас Эдисон в 1879 году сделал долговечную лампочку и наладил её массовый выпуск. 💡"},
  {"q":["кто изобрел телефон","кто придумал телефон","когда изобрели телефон","кто изобрёл телефон первым"],"a":"Патент на телефон первым получил Александр Белл в 1876 году, поэтому изобретателем телефона обычно называют его. Похожие устройства делали и другие изобретатели, например итальянец Антонио Меуччи. Первая фраза Белла по телефону была обращена к помощнику: «Мистер Ватсон, идите сюда, вы мне нужны». ☎️"},
  {"q":["кто изобрел радио","кто придумал радио","кто изобрёл радио попов или маркони","когда изобрели радио"],"a":"В России изобретателем радио считают Александра Попова — в 1895 году он показал свой радиоприёмник, поэтому 7 мая у нас отмечают День радио. Примерно в то же время над радио работал итальянец Гульельмо Маркони, который первым получил на него патент. 📻"},
  {"q":["кто изобрел интернет","кто придумал интернет","когда появился интернет","кто создал интернет"],"a":"Интернет придумал не один человек. В 1969 году в США заработала сеть ARPANET — его предок, а в 1989–1991 годах учёный Тим Бернерс-Ли создал «Всемирную паутину» — сайты и ссылки, которыми мы пользуемся сегодня. 🌐"},
  {"q":["кто изобрел компьютер","кто придумал компьютер","какой был первый компьютер","когда появился первый компьютер"],"a":"У компьютера много «родителей». Ещё в XIX веке Чарльз Бэббидж придумал вычислительную машину, а первые электронные компьютеры появились в 1940-х годах — они занимали целые комнаты. Сегодняшний телефон мощнее их в миллионы раз! 💻"},
  {"q":["кто изобрел телевизор","кто придумал телевизор","когда появился телевизор","кто придумал телик"],"a":"Телевизор придумали несколько изобретателей. В 1920-х годах шотландец Джон Бэрд показал механическое телевидение, а электронное создавали Владимир Зворыкин, уехавший из России в США, и американец Фило Фарнсуорт. 📺"},
  {"q":["кто изобрел самолет","кто придумал самолет","кто первый полетел на самолете","когда появился первый самолет"],"a":"Первый управляемый полёт на самолёте с мотором совершили американцы братья Уилбур и Орвилл Райт 17 декабря 1903 года. Он длился всего 12 секунд, а сейчас самолёты перелетают океаны! ✈️"},
  {"q":["кто изобрел машину","кто придумал автомобиль","какая была первая машина","кто изобрел автомобиль"],"a":"Первый автомобиль с бензиновым двигателем создал немецкий инженер Карл Бенц — он получил на него патент в 1886 году. У этой машины было всего три колеса! 🚗"},
  {"q":["кто изобрел колесо","кто придумал колесо","когда появилось колесо","кто первый придумал колесо"],"a":"Имя изобретателя колеса неизвестно — это было очень давно. Учёные считают, что колесо появилось примерно 5500 лет назад; древнейшие находки сделаны в Месопотамии и Европе. 🛞"},
  {"q":["кто придумал письменность","кто изобрел буквы","когда люди начали писать","кто первый придумал писать"],"a":"Одну из первых систем письма придумали шумеры в Месопотамии около 5000 лет назад: они выдавливали значки палочкой на глиняных табличках — это клинопись. Примерно тогда же появились египетские иероглифы. ✍️"},
  {"q":["кто изобрел книгопечатание","кто придумал печатать книги","кто напечатал первую книгу","кто первопечатник"],"a":"В Европе печатный станок изобрёл Иоганн Гутенберг в середине XV века (а в Китае печатали ещё раньше). В России первую точно датированную книгу «Апостол» напечатал Иван Фёдоров в 1564 году. 📚"},
  {"q":["кто изобрел велосипед","кто придумал велосипед","какой был первый велосипед","когда появился велосипед"],"a":"Первый велосипед придумал немец Карл Дрез в 1817 году. У него не было педалей — нужно было отталкиваться ногами от земли, как на беговеле! Педали появились позже. 🚲"},
  {"q":["кто изобрел мобильный телефон","когда появился первый мобильный телефон","кто первый позвонил по мобильному телефону","кто придумал сотовый телефон"],"a":"Первый звонок по сотовому телефону, который можно носить в руке, сделал инженер Мартин Купер из компании Motorola в 1973 году — тот телефон весил около килограмма. А смартфоны с большим сенсорным экраном стали очень популярными после выхода iPhone в 2007 году. 📱"},
  {"q":["кто придумал тетрис","кто создал тетрис","кто изобрел тетрис","тетрис русская игра"],"a":"Тетрис придумал советский программист Алексей Пажитнов в 1984 году в Москве. Эта игра стала одной из самых известных в мире! 🧱"},
  {"q":["кто создал майнкрафт","кто придумал minecraft","кто сделал майн","когда появился майнкрафт"],"a":"Minecraft придумал шведский программист Маркус Перссон по прозвищу Notch — первая версия появилась в 2009 году. Сейчас игрой владеет компания Microsoft, и это самая продаваемая видеоигра в истории. ⛏️"},
  {"q":["кто создал ютуб","кто придумал youtube","когда появился ютуб","кто основал ютуб"],"a":"YouTube создали в 2005 году трое друзей — Чад Хёрли, Стив Чен и Джавед Карим. Самое первое видео было снято в зоопарке у вольера со слонами. Позже YouTube купила компания Google. 🎬"},
  {"q":["кто такой гагарин","кто первый полетел в космос","юрий гагарин","кто был первым космонавтом"],"a":"Юрий Гагарин — первый человек в космосе! 12 апреля 1961 года на корабле «Восток-1» он облетел Землю за 108 минут и сказал знаменитое «Поехали!». С тех пор 12 апреля — День космонавтики. 🚀"},
  {"q":["кто первый человек на луне","кто первым ступил на луну","кто был на луне","нил армстронг"],"a":"Первым человеком на Луне стал американский астронавт Нил Армстронг в июле 1969 года, во время экспедиции «Аполлон-11». Он сказал: «Это один маленький шаг для человека, но гигантский скачок для всего человечества». Всего с 1969 по 1972 год по Луне прошли 12 американских астронавтов. 🌕"},
  {"q":["кто первый вышел в открытый космос","алексей леонов","кто первым вышел из корабля в космос","первый выход в открытый космос"],"a":"Первым в открытый космос вышел советский космонавт Алексей Леонов 18 марта 1965 года — он провёл за бортом корабля около 12 минут. А ещё Леонов был художником и рисовал космос! 👨‍🚀"},
  {"q":["кто первая женщина в космосе","валентина терешкова","первая женщина космонавт","какая женщина первая полетела в космос"],"a":"Первой женщиной в космосе стала Валентина Терешкова — она полетела 16 июня 1963 года на корабле «Восток-6» и провела в космосе почти трое суток. 👩‍🚀"},
  {"q":["кто такие белка и стрелка","первая собака в космосе","какое животное первым полетело в космос","собака лайка"],"a":"Первыми в космос, ещё в 1947 году, слетали крошечные мушки-дрозофилы. Первые собаки — Дезик и Цыган — поднялись на ракете в космос в 1951 году и вернулись. В 1957 году собака Лайка первой из животных облетела Землю по орбите, а в 1960 году Белка и Стрелка провели на орбите сутки и благополучно вернулись домой — это помогло подготовить полёт человека. 🐕"},
  {"q":["когда запустили первый спутник","какой был первый спутник","первый искусственный спутник земли","кто запустил первый спутник"],"a":"Первый искусственный спутник Земли запустил СССР 4 октября 1957 года. Это был металлический шар диаметром 58 сантиметров с четырьмя антеннами, который подавал сигнал «бип-бип». С этого дня началась космическая эра! 🛰️"},
  {"q":["кто такой королев","сергей королев","кто построил ракету для гагарина","главный конструктор кто это"],"a":"Сергей Королёв — главный конструктор советских ракет и космических кораблей. Под его руководством запустили первый спутник Земли и отправили в космос Юрия Гагарина. 🚀"},
  {"q":["кто такой пушкин","александр пушкин","что написал пушкин","почему пушкин великий"],"a":"Александр Сергеевич Пушкин (1799–1837) — великий русский поэт, его называют «солнцем русской поэзии». Он написал роман в стихах «Евгений Онегин», «Сказку о рыбаке и рыбке», «Сказку о царе Салтане» и множество прекрасных стихов. 📜"},
  {"q":["кто такой илон маск","илон маск","чем знаменит илон маск","кто такой маск"],"a":"Илон Маск — известный предприниматель. Он основал компанию SpaceX, которая строит многоразовые ракеты и космические корабли, а ещё прославился электромобилями Tesla. Его часто называют одним из самых богатых людей мира. 🚀"},
  {"q":["кто такой эйнштейн","альберт эйнштейн","чем знаменит эйнштейн","что придумал эйнштейн"],"a":"Альберт Эйнштейн — один из самых известных физиков в истории. Он создал теорию относительности, которая объясняет, как связаны время, пространство и гравитация, и вывел знаменитую формулу E = mc². А Нобелевскую премию по физике он получил за объяснение фотоэффекта — того, как свет выбивает электроны из металла. 🧠"},
  {"q":["кто такой ньютон","исаак ньютон","что открыл ньютон","ньютон и яблоко"],"a":"Исаак Ньютон — английский учёный, открывший закон всемирного тяготения и законы движения. Есть известная легенда, что мысль о тяготении пришла к нему, когда он увидел падающее яблоко. 🍎"},
  {"q":["кто такой ломоносов","михаил ломоносов","чем знаменит ломоносов","что сделал ломоносов"],"a":"Михаил Ломоносов — великий русский учёный XVIII века. Юношей он ушёл с рыбным обозом из деревни под Архангельском в Москву учиться, стал химиком, физиком и поэтом, а по его замыслу в 1755 году основали Московский университет. 🎓"},
  {"q":["кто придумал таблицу менделеева","кто такой менделеев","дмитрий менделеев","что открыл менделеев"],"a":"Таблицу химических элементов составил русский учёный Дмитрий Менделеев в 1869 году. Он так хорошо понял закономерности, что оставил в таблице пустые клетки и предсказал элементы, которые открыли только позже! ⚗️"},
  {"q":["кто такой петр первый","петр 1","чем знаменит петр великий","кто основал санкт петербург"],"a":"Пётр I (Пётр Великий) — русский царь и первый российский император. Он построил флот, основал Санкт-Петербург в 1703 году и сделал Россию сильной морской державой. ⚓"},
  {"q":["кто открыл америку","кто такой христофор колумб","когда открыли америку","колумб открыл америку"],"a":"В 1492 году мореплаватель Христофор Колумб доплыл до островов у берегов Америки — он думал, что попал в Индию! Но ещё около 1000 года туда добирались викинги во главе с Лейфом Эрикссоном, а коренные народы жили в Америке тысячи лет. 🧭"},
  {"q":["кто первым совершил кругосветное путешествие","кто такой магеллан","первое кругосветное путешествие","кто первый обплыл землю"],"a":"Первое кругосветное плавание совершила экспедиция Фернана Магеллана в 1519–1522 годах. Сам Магеллан погиб в пути, а домой корабль привёл Хуан Себастьян Элькано. Так люди на деле убедились, что вокруг Земли можно проплыть. 🌍"},
  {"q":["кто нарисовал мону лизу","кто такой леонардо да винчи","мона лиза кто автор","кто нарисовал джоконду"],"a":"«Мону Лизу» («Джоконду») написал итальянский художник Леонардо да Винчи в начале XVI века. Он был ещё и изобретателем: рисовал чертежи летательных машин задолго до появления самолётов. Картина хранится в Лувре, в Париже. 🎨"},
  {"q":["кто такой никола тесла","тесла кто это","что изобрел тесла","никола тесла"],"a":"Никола Тесла — знаменитый изобретатель сербского происхождения, работавший в США. Он много сделал для использования переменного тока, который сегодня течёт в наших розетках, и придумал катушку Теслы, создающую настоящие молнии. В его честь назвали электромобили Tesla. ⚡"},
  {"q":["кто такой стив джобс","кто создал apple","кто придумал айфон","кто основал эпл"],"a":"Компанию Apple основали в 1976 году Стив Джобс, Стив Возняк и Рональд Уэйн. Стив Джобс прославился тем, что руководил созданием iPhone и представил его в 2007 году. 🍏"},
  {"q":["кто написал гарри поттера","кто автор гарри поттера","кто придумал гарри поттера","гарри поттер кто написал"],"a":"Книги о Гарри Поттере написала британская писательница Джоан Роулинг. Всего в серии 7 книг, первая — «Гарри Поттер и философский камень» — вышла в 1997 году. ⚡"},
  {"q":["кто написал войну и мир","война и мир автор","кто автор войны и мира","война и мир кто написал"],"a":"Роман «Война и мир» написал Лев Николаевич Толстой. Это огромная книга о войнах России с Наполеоном, в том числе об Отечественной войне 1812 года, и о жизни нескольких семей — в ней больше 500 героев! 📖"},
  {"q":["кто написал евгения онегина","евгений онегин автор","кто автор евгения онегина","онегин кто написал"],"a":"«Евгения Онегина» написал Александр Сергеевич Пушкин. Это роман в стихах — Пушкин работал над ним больше семи лет. 📜"},
  {"q":["кто написал преступление и наказание","преступление и наказание автор","кто такой достоевский","раскольников кто написал"],"a":"Фёдор Михайлович Достоевский — великий русский писатель. Роман «Преступление и наказание» он написал в 1866 году. Это книга о студенте Родионе Раскольникове и о совести, её читают в старших классах. 📖"},
  {"q":["кто написал мастер и маргарита","мастер и маргарита автор","кто такой булгаков","кто написал мастера и маргариту"],"a":"Михаил Булгаков — русский писатель и драматург, автор романа «Мастер и Маргарита». При его жизни роман так и не напечатали — он вышел только в 1966–1967 годах. А ещё в книге есть знаменитый говорящий кот Бегемот! 🐈‍⬛"},
  {"q":["кто написал маленького принца","маленький принц автор","кто автор маленького принца","маленький принц кто написал"],"a":"«Маленького принца» написал французский писатель и лётчик Антуан де Сент-Экзюпери в 1943 году, и рисунки в книге тоже его. Оттуда знаменитая фраза: «Ты навсегда в ответе за всех, кого приручил». 🌹"},
  {"q":["кто написал алису в стране чудес","алиса в стране чудес автор","кто такой льюис кэрролл","кто придумал алису в стране чудес"],"a":"«Алису в Стране чудес» написал английский писатель и математик Льюис Кэрролл. Книга вышла в 1865 году, а придумал он эту историю для девочки Алисы Лидделл. 🐇"},
  {"q":["кто написал буратино","кто придумал буратино","золотой ключик автор","буратино и пиноккио"],"a":"Сказку «Золотой ключик, или Приключения Буратино» написал Алексей Николаевич Толстой в 1936 году. Он по-своему пересказал итальянскую сказку Карло Коллоди о Пиноккио. 🔑"},
  {"q":["кто написал винни пуха","винни пух автор","кто придумал винни пуха","кто автор винни-пуха"],"a":"Винни-Пуха придумал английский писатель Алан Милн — первая книга о нём вышла в 1926 году. На русский язык её замечательно пересказал Борис Заходер. 🍯"},
  {"q":["кто написал шерлока холмса","шерлок холмс автор","кто придумал шерлока холмса","кто такой конан дойл"],"a":"Сыщика Шерлока Холмса придумал британский писатель Артур Конан Дойл. Первая повесть о нём — «Этюд в багровых тонах» — вышла в 1887 году. 🔍"},
  {"q":["кто написал колобка","колобок автор","кто придумал колобок","кто написал сказку колобок"],"a":"У «Колобка» нет одного автора — это русская народная сказка. Её веками пересказывали люди, а потом записали собиратели сказок, например Александр Афанасьев. 🍞"},
  {"q":["кто придумал чебурашку","кто написал простоквашино","кто автор дяди федора","эдуард успенский"],"a":"Чебурашку, крокодила Гену, дядю Фёдора, кота Матроскина и пса Шарика придумал писатель Эдуард Успенский. Книга «Крокодил Гена и его друзья» вышла в 1966 году. 🐊"},
  {"q":["кто написал айболита","кто написал мойдодыр","кто такой чуковский","кто написал муху цокотуху"],"a":"«Айболита», «Мойдодыра», «Муху-Цокотуху», «Телефон» и «Федорино горе» написал Корней Иванович Чуковский — один из самых любимых детских поэтов. 📚"},
  {"q":["какая самая продаваемая книга","самая популярная книга в мире","какую книгу больше всего читают","самая известная книга в мире"],"a":"Самой распространённой книгой в мире считается Библия — её напечатано несколько миллиардов экземпляров. Среди книг для детей одни из самых продаваемых — «Маленький принц» и серия о Гарри Поттере. 📚"},
  {"q":["когда была великая отечественная война","когда началась война 1941","когда закончилась великая отечественная война","что такое день победы"],"a":"Великая Отечественная война шла с 22 июня 1941 года по 9 мая 1945 года. Наш народ победил, поэтому 9 мая мы празднуем День Победы и вспоминаем всех, кто защищал Родину. 🎖️"},
  {"q":["кто построил пирамиды","как построили египетские пирамиды","сколько лет пирамидам","зачем построили пирамиды"],"a":"Пирамиды построили древние египтяне как гробницы для своих царей — фараонов. Самой большой, пирамиде Хеопса, около 4500 лет; её строили тысячи рабочих, перетаскивая огромные каменные блоки. 🏜️"},
  {"q":["когда появились олимпийские игры","кто придумал олимпиаду","откуда олимпийские игры","когда была первая олимпиада"],"a":"Олимпийские игры появились в Древней Греции — первые Игры, о которых есть записи, прошли в 776 году до нашей эры. Современные Олимпиады возродил француз Пьер де Кубертен, и первые из них прошли в Афинах в 1896 году. 🏅"},
  {"q":["семь чудес света","какие есть чудеса света","7 чудес света список","какие чудеса света сохранились"],"a":"Семь чудес древнего мира: пирамида Хеопса, Висячие сады Семирамиды, статуя Зевса в Олимпии, храм Артемиды в Эфесе, Мавзолей в Галикарнасе, Колосс Родосский и Александрийский маяк. До наших дней сохранилась только пирамида Хеопса! 🏛️"},
  {"q":["кто открыл антарктиду","когда открыли антарктиду","кто первый увидел антарктиду","беллинсгаузен и лазарев"],"a":"Антарктиду открыла русская экспедиция Фаддея Беллинсгаузена и Михаила Лазарева в январе 1820 года на кораблях «Восток» и «Мирный». ❄️"},
  {"q":["кто придумал русский алфавит","кто создал кириллицу","кто придумал буквы русского языка","кирилл и мефодий"],"a":"Братья Кирилл и Мефодий около 863 года создали славянскую азбуку. Кириллицу назвали в честь Кирилла — её, скорее всего, составили его ученики, и из неё вырос наш русский алфавит. 🔤"},
  {"q":["какая самая большая страна","самая большая страна в мире","какая страна самая большая по площади","самая огромная страна"],"a":"Самая большая страна в мире — Россия! Её площадь — около 17,1 миллиона квадратных километров, это примерно девятая часть всей суши Земли. 🇷🇺"},
  {"q":["какая самая маленькая страна","самая маленькая страна в мире","самое маленькое государство","ватикан это страна"],"a":"Самая маленькая страна — Ватикан. Её площадь меньше половины квадратного километра, и она находится прямо внутри города Рима. Там живёт Папа Римский. ⛪"},
  {"q":["какая самая высокая гора","самая высокая гора в мире","высота эвереста","какая гора выше всех"],"a":"Самая высокая гора на Земле — Эверест (Джомолунгма) в Гималаях, около 8849 метров над уровнем моря. Первыми на вершину поднялись Эдмунд Хиллари и Тенцинг Норгей в 1953 году. 🏔️"},
  {"q":["какая самая длинная река","самая длинная река в мире","нил или амазонка","какая река длиннее всех"],"a":"Обычно самой длинной рекой мира называют Нил в Африке — около 6650 км. Но некоторые учёные считают, что Амазонка в Южной Америке немного длиннее: всё зависит от того, где считать её начало. А по количеству воды Амазонка точно на первом месте! 🌊"},
  {"q":["какая самая длинная река в россии","самая длинная река россии","самая большая река россии","длинная река в россии"],"a":"Если считать вместе с притоком Иртышом, самая длинная река России — Обь: около 5400 км. Из рек, которые целиком текут по России, самая длинная — Лена, больше 4000 км. Самая полноводная река России — Енисей, а Волга — самая длинная река Европы. 🏞️"},
  {"q":["какое самое глубокое место на земле","марианская впадина","самое глубокое место в океане","какая глубина марианской впадины"],"a":"Самое глубокое место на Земле — Марианская впадина в Тихом океане, её глубина почти 11 километров! Если бы туда опустили Эверест, его вершина оказалась бы под водой примерно на 2 километра. 🌊"},
  {"q":["какое самое глубокое озеро","байкал","сколько глубина байкала","чем знаменит байкал"],"a":"Самое глубокое озеро в мире — Байкал в Сибири, его глубина 1642 метра. Ему больше 25 миллионов лет, и в нём примерно пятая часть всей пресной озёрной воды планеты. А ещё там живёт нерпа — пресноводный тюлень! 🦭"},
  {"q":["какой самый большой океан","самый большой океан в мире","самый глубокий океан","тихий океан самый большой"],"a":"Самый большой и самый глубокий океан — Тихий. Он занимает почти треть поверхности Земли — это больше, чем вся суша вместе взятая! 🌏"},
  {"q":["какой самый большой материк","самый большой континент","какой материк больше всех","евразия самая большая"],"a":"Самый большой материк — Евразия: около 54 миллионов квадратных километров. На нём находятся и Европа, и Азия, и вся Россия. 🌍"},
  {"q":["сколько материков на земле","сколько всего материков","какие есть материки","сколько континентов"],"a":"В России обычно выделяют 6 материков: Евразия, Африка, Северная Америка, Южная Америка, Австралия и Антарктида. В некоторых странах считают по-другому, например 7 континентов, разделяя Европу и Азию. 🗺️"},
  {"q":["сколько океанов на земле","какие есть океаны","сколько всего океанов","назови все океаны"],"a":"Сейчас обычно называют пять океанов: Тихий, Атлантический, Индийский, Северный Ледовитый и Южный. Раньше в России чаще считали четыре — без Южного океана вокруг Антарктиды. 🌊"},
  {"q":["какая самая большая пустыня","самая большая пустыня в мире","сахара самая большая пустыня","какая пустыня больше всех"],"a":"Самая большая жаркая пустыня — Сахара в Африке, около 9 миллионов км². Но учёные называют пустыней любое место, где выпадает очень мало осадков, поэтому самая большая пустыня вообще — ледяная Антарктида! 🏜️"},
  {"q":["какой самый большой остров","самый большой остров в мире","гренландия самый большой остров","какой остров больше всех"],"a":"Самый большой остров в мире — Гренландия, около 2,1 миллиона квадратных километров, и большая её часть покрыта толстым льдом. Австралию островом не считают — это материк. 🧊"},
  {"q":["какое самое большое озеро","самое большое озеро в мире","каспийское море это озеро","какое озеро больше всех"],"a":"Самое большое озеро по площади — Каспийское море. Его называют морем, потому что оно огромное и вода в нём солоноватая, но на самом деле это озеро: оно не соединяется с океаном. 🌊"},
  {"q":["какой самый высокий водопад","самый высокий водопад в мире","водопад анхель","где самый высокий водопад"],"a":"Самый высокий водопад в мире — Анхель в Венесуэле, его высота 979 метров. Вода падает так долго, что часть её превращается в туман, не долетая до земли. 💧"},
  {"q":["какое самое холодное место на земле","где самый сильный мороз","самое холодное место в россии","оймякон"],"a":"Самое холодное место — Антарктида: на станции «Восток» в 1983 году измерили −89,2 °C. А самые холодные места, где живут люди, — Оймякон и Верхоянск в Якутии, там бывали морозы около −68 °C. 🥶"},
  {"q":["какое самое жаркое место на земле","где самая высокая температура","самое жаркое место в мире","где жарче всего на земле"],"a":"Рекорд жары записан в Долине Смерти в США — +56,7 °C в 1913 году. А по средней температуре за год одно из самых жарких мест — пустыня Данакиль в Эфиопии. ☀️"},
  {"q":["сколько стран в мире","сколько всего стран на земле","сколько государств в мире","сколько стран существует"],"a":"В мире около 200 стран. В Организацию Объединённых Наций входят 193 государства, и есть ещё несколько стран, которые признают не все. 🌐"},
  {"q":["сколько людей на земле","сколько человек живет на планете","какое население земли","сколько людей в мире"],"a":"На Земле живёт больше 8 миллиардов человек! Если считать их по одному в секунду без перерыва, на это ушло бы больше 250 лет. 👨‍👩‍👧‍👦"},
  {"q":["какая самая населенная страна","в какой стране больше всего людей","китай или индия больше людей","самая многолюдная страна"],"a":"Больше всего людей живёт в Индии — более 1,4 миллиарда человек. В 2023 году она обогнала по населению Китай, где живёт около 1,4 миллиарда. 🇮🇳"},
  {"q":["какая столица сша","столица америки","столица сша нью йорк","главный город америки"],"a":"Столица США — Вашингтон, а не Нью-Йорк, как многие думают! Нью-Йорк — самый большой город страны, а в Вашингтоне находятся Белый дом и Конгресс. 🇺🇸"},
  {"q":["какое самое высокое здание","самый высокий небоскреб в мире","бурдж халифа","самое высокое здание в россии"],"a":"Самое высокое здание в мире — небоскрёб Бурдж-Халифа в Дубае, его высота 828 метров. А самое высокое здание России и Европы — Лахта-центр в Санкт-Петербурге, 462 метра. 🏙️"},
  {"q":["какая самая высокая гора в россии","эльбрус","высота эльбруса","самая высокая гора европы"],"a":"Самая высокая гора России и Европы — Эльбрус на Кавказе, 5642 метра. Это спящий вулкан с двумя вершинами, покрытыми снегом круглый год. 🏔️"},
  {"q":["видна ли китайская стена из космоса","какая длина великой китайской стены","великая китайская стена","самая длинная стена в мире"],"a":"Великая Китайская стена — самое длинное сооружение в мире: со всеми ответвлениями больше 21 000 километров. Но вопреки известному мифу, с орбиты её почти невозможно разглядеть невооружённым глазом — она слишком узкая. 🧱"},
  {"q":["что такое деньги","зачем нужны деньги","для чего люди придумали деньги","почему нельзя без денег"],"a":"Деньги — это удобный способ обмениваться: вместо того чтобы менять, например, корову на сапоги, люди платят деньгами за товары и работу. Деньги работают потому, что все люди договорились им доверять. 💰"},
  {"q":["откуда появились деньги","кто придумал деньги","какие были первые деньги","когда появились монеты"],"a":"Сначала люди просто менялись вещами, потом деньгами служили ракушки, соль, шкурки и зерно. Первые монеты появились больше 2500 лет назад в Лидии (на территории современной Турции), а бумажные деньги придумали в Китае. 🪙"},
  {"q":["какие деньги в россии","какая валюта в россии","сколько копеек в рубле","какая валюта в америке"],"a":"В России деньги называются рубль, в одном рубле 100 копеек. В США — доллар, во многих странах Европы — евро, в Китае — юань, а в Японии — иена. 💵"},
  {"q":["почему нельзя напечатать много денег","почему государство не печатает больше денег","почему нельзя всем раздать много денег","что будет если напечатать много денег"],"a":"Если напечатать очень много денег, а товаров больше не станет, то всё просто подорожает — это называется инфляция. Деньги чего-то стоят только потому, что на них можно что-то купить. 📈"},
  {"q":["что такое банк","зачем нужен банк","как работает банк","что делают в банке"],"a":"Банк — это место, где люди хранят деньги, получают и переводят их. Банк даёт деньги в долг (кредит) и берёт за это плату — процент, а тем, кто держит у него деньги на вкладе, сам немного доплачивает. 🏦"},
  {"q":["что такое биткоин","что такое криптовалюта","кто придумал биткоин","как работает биткоин"],"a":"Биткоин — это цифровые деньги, которые существуют только в компьютерах, без монет и купюр. Его придумал в 2008–2009 годах человек или группа людей под псевдонимом Сатоши Накамото — кто это на самом деле, до сих пор неизвестно! 💻"},
  {"q":["кто самый богатый человек в мире","самый богатый человек","кто богаче всех","у кого больше всего денег"],"a":"Это место часто меняется, потому что богатство таких людей зависит от стоимости их компаний. В последние годы самым богатым человеком мира чаще всего называли Илона Маска. 💼"},
  {"q":["сколько языков в мире","сколько всего языков на земле","сколько языков существует","сколько есть языков"],"a":"В мире около 7000 языков! Но многие из них очень маленькие — на них говорят всего несколько тысяч или даже сотен человек. 🗣️"},
  {"q":["какой самый распространенный язык","на каком языке говорят больше всего людей","самый популярный язык в мире","самый главный язык в мире"],"a":"Больше всего людей говорит по-английски, если считать тех, кто выучил его как второй язык. А по числу людей, для которых язык родной, первое место у китайского. Русский тоже входит в десятку самых распространённых языков! 🌍"},
  {"q":["сколько букв в русском алфавите","сколько букв в алфавите","сколько гласных букв в русском","сколько согласных букв"],"a":"В русском алфавите 33 буквы: 10 гласных, 21 согласная и ещё два знака — твёрдый (ъ) и мягкий (ь), которые сами не обозначают звуков. 🔤"},
  {"q":["сколько букв в английском алфавите","английский алфавит сколько букв","сколько букв в английском","сколько букв в латинице"],"a":"В английском алфавите 26 букв — от A до Z. Гласных букв пять: A, E, I, O, U, а иногда гласной считают и Y. 🔠"},
  {"q":["какое самое длинное слово в русском языке","самое длинное слово","самое длинное русское слово","какое слово самое длинное"],"a":"В Книгу рекордов Гиннесса попало слово «рентгеноэлектрокардиографического» — в нём 33 буквы, как в алфавите! Хотя в словарях можно найти и другие очень длинные слова. 📏"},
  {"q":["как сказать привет на английском","как будет привет на других языках","привет по английски","как сказать привет по-немецки"],"a":"По-английски — Hello (хэллоу) или Hi (хай), по-немецки — Hallo (халло), по-французски — Bonjour (бонжур), по-испански — Hola (ола), по-китайски — Nǐ hǎo (ни хао). 👋"},
  {"q":["кто самый быстрый человек","самый быстрый человек в мире","усейн болт","кто быстрее всех бегает"],"a":"Самый быстрый бегун в истории — Усэйн Болт с Ямайки. В 2009 году он пробежал 100 метров за 9,58 секунды, разгоняясь примерно до 44 км/ч! 🏃"},
  {"q":["какой самый популярный вид спорта","самый популярный спорт в мире","какой спорт самый любимый","футбол самый популярный"],"a":"Самый популярный вид спорта в мире — футбол: в него играют и за ним следят миллиарды людей. Чемпионат мира по футболу проходит раз в четыре года. ⚽"},
  {"q":["какая самая популярная игра в мире","самая продаваемая игра","самая популярная видеоигра","какая игра продалась больше всех"],"a":"Самая продаваемая видеоигра в истории — Minecraft: продано больше 300 миллионов копий! А одна из самых знаменитых игр всех времён — Тетрис. 🎮"},
  {"q":["что быстрее всего на свете","какая самая большая скорость","что самое быстрое во вселенной","скорость света"],"a":"Быстрее всего на свете движется свет — около 300 000 километров в секунду! Свет от Солнца долетает до Земли примерно за 8 минут, а быстрее света, насколько известно учёным, ничего не бывает. 💫"},
];
